-- Let a child eat the slack in a horizontal list: `reserve` is the width its
-- siblings and the gaps between them take up.
--
-- This used to add a UIFlexItem in Fill mode, and that is what made every row
-- label render blank in 2.7.0. Flex GROWS an item from its base size, and the
-- labels had a base width of 100% - so the pass had negative slack to hand out
-- and collapsed them to nothing. The buttons were fine because their base width
-- was already 0. Explicit arithmetic is one line, needs no guessing about how
-- flex distributes, and cannot fail silently: a wrong `reserve` gives a label
-- that is slightly the wrong width, not an invisible one.
local function flexFill(instance, reserve, heightScale, heightOffset)
    if not reserve then return false end
    -- Height is passed in rather than read back off the instance: every caller
    -- wants full height, and reading Size just to rebuild it was one more thing
    -- to get wrong.
    instance.Size = UDim2.new(1, -reserve, heightScale or 1, heightOffset or 0)
    return true
end

local function hlist(instance, gap)
    local l = Instance.new("UIListLayout")
    l.FillDirection = Enum.FillDirection.Horizontal
    l.VerticalAlignment = Enum.VerticalAlignment.Center
    l.Padding = UDim.new(0, gap or Theme.GapMd)
    l.SortOrder = Enum.SortOrder.LayoutOrder
    l.Parent = instance
    return l
end

local function label(parent, text, style, order)
    local st = STYLES[style] or STYLES.rowLabel
    local l = Instance.new("TextLabel")
    l.BackgroundTransparency = 1
    l.Text = text or ""
    l.TextColor3 = Theme[st.color]
    l.TextSize = st.size
    l.TextXAlignment = Enum.TextXAlignment.Left
    l.TextYAlignment = Enum.TextYAlignment.Center
    l.LayoutOrder = order or 1
    l.Size = UDim2.new(1, 0, 1, 0)
    setFont(l, st.family, st.weight)
    l.Parent = parent
    return l
end

-- The accent gradient, in one place. `rotation` 0 is left-to-right.
local function accentGradient(instance, rotation)
    local g = Instance.new("UIGradient")
    g.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Theme.AccentA),
        ColorSequenceKeypoint.new(0.5, Theme.AccentMid),
        ColorSequenceKeypoint.new(1, Theme.AccentB),
    })
    g.Rotation = rotation or 0
    g.Parent = instance
    return g
end

-- The window body fade: colour and alpha together, as one UIGradient.
local function bodyGradient(instance)
    local g = Instance.new("UIGradient")
    g.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Theme.BodyTop),
        ColorSequenceKeypoint.new(0.45, Theme.BodyMid),
        ColorSequenceKeypoint.new(1, Theme.BodyBot),
    })
    g.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, Theme.BodyTopA),
        NumberSequenceKeypoint.new(0.45, Theme.BodyMidA),
        NumberSequenceKeypoint.new(1, Theme.BodyBotA),
    })
    g.Rotation = 90
    g.Parent = instance
    return g
end

-- Elevation. Roblox has no box-shadow and the kit takes no image assets, so a
-- soft edge is approximated with N frames behind the panel, each a little
-- larger and pushed a little further down, all at low alpha. Eight at 0.07
-- accumulate to about 0.44 in the middle, which is the design's 0.45.
local function shadow(frame, layers, step, drop, alpha, radius)
    layers = layers or 8
    step = step or 2.2
    drop = drop or 14
    alpha = alpha or 0.07
    radius = radius or Theme.RadiusLg
    local holder = Instance.new("Frame")
    holder.Name = "Shadow"
    holder.BackgroundTransparency = 1
    holder.Size = UDim2.fromScale(1, 1)
    holder.ZIndex = frame.ZIndex - 1
    holder.Parent = frame

    for i = 1, layers do
        local spread = i * step
        local offset = drop * (i / layers)
        local layer = Instance.new("Frame")
        layer.Name = "L" .. i
        layer.BackgroundColor3 = Color3.new(0, 0, 0)
        layer.BackgroundTransparency = 1 - alpha
        layer.BorderSizePixel = 0
        layer.ZIndex = frame.ZIndex - 1
        layer.Position = UDim2.fromOffset(-spread, -spread + offset)
        layer.Size = UDim2.new(1, spread * 2, 1, spread * 2)
        corner(layer, radius + spread)
        layer.Parent = holder
    end
    return holder
end

-- =========================================================================
-- Tooltip: one shared box, shown after a second of hovering, following the
-- mouse. Everything with an explanation registers through `tip`.
-- =========================================================================
local Tip = { frame = nil, label = nil, target = nil, showAt = nil, conn = nil }

local function ensureTip(screenGui)
    if Tip.frame and Tip.frame.Parent then return end
    local f = Instance.new("Frame")
    f.Name = "Tooltip"
    f.BackgroundColor3 = Color3.fromHex("3a3a42")
    f.BorderSizePixel = 0
    f.Visible = false
    f.ZIndex = 500
    f.AutomaticSize = Enum.AutomaticSize.XY
    f.Size = UDim2.fromOffset(0, 0)
    f.Parent = screenGui
    corner(f, Theme.RadiusSm)
    stroke(f, Color3.fromHex("4a4a55"), 1)
    pad(f, 6, 8, 6, 8)

    local l = Instance.new("TextLabel")
    l.BackgroundTransparency = 1
    l.AutomaticSize = Enum.AutomaticSize.XY
    l.Size = UDim2.fromOffset(0, 0)
    l.TextWrapped = true
    l.TextXAlignment = Enum.TextXAlignment.Left
    l.TextYAlignment = Enum.TextYAlignment.Top
    l.TextColor3 = Color3.fromHex("e8e8ee")
    l.TextSize = 11
    l.ZIndex = 501
    setFont(l, "sans", Enum.FontWeight.Medium)
    l.Parent = f

    -- AutomaticSize with wrapping needs an upper bound or a long line runs off
    -- the screen; 240px matches the design's tooltip.
    local size = Instance.new("UISizeConstraint")
    size.MaxSize = Vector2.new(240, math.huge)
    size.Parent = l

    Tip.frame, Tip.label = f, l

    -- One clock for every tooltip: the delay, and the follow.
    if Tip.conn then Tip.conn:Disconnect() end
    Tip.conn = RunService.RenderStepped:Connect(function()
        if not Tip.target then return end
        local now = os.clock()
        if not Tip.frame.Visible then
            if now < Tip.showAt then return end
            Tip.frame.Visible = true
        end
        local m = UserInputService:GetMouseLocation()
        local camera = workspace.CurrentCamera
        local viewport = camera and camera.ViewportSize or Vector2.new(1920, 1080)
        local w, h = Tip.frame.AbsoluteSize.X, Tip.frame.AbsoluteSize.Y
        -- Flip to the other side of the cursor near an edge rather than
        -- letting the box hang off screen.
        local x = (m.X + 16 + w > viewport.X) and (m.X - 16 - w) or (m.X + 16)
        local y = (m.Y + 18 + h > viewport.Y) and (m.Y - 12 - h) or (m.Y + 18)
        Tip.frame.Position = UDim2.fromOffset(x, y)
    end)
end

local function hideTip()
    Tip.target = nil
    if Tip.frame then Tip.frame.Visible = false end
end

-- Attaches an explanation to any GuiObject.
local function tip(instance, text)
    if not text or text == "" then return instance end
    instance.MouseEnter:Connect(function()
        if not Tip.frame then return end
        Tip.target = instance
        Tip.showAt = os.clock() + 1.0
        Tip.frame.Visible = false
        Tip.label.Text = text
    end)
    instance.MouseLeave:Connect(function()
        if Tip.target == instance then hideTip() end
    end)
    -- A destroyed widget must not leave its tooltip stranded on screen.
    instance.AncestryChanged:Connect(function()
        if not instance:IsDescendantOf(game) and Tip.target == instance then hideTip() end
    end)
    return instance
end

-- =========================================================================
-- Primitives
-- =========================================================================

-- Chevron: two rounded bars, never a glyph and never an image.
local function chevron(parent)
    local holder = Instance.new("Frame")
    holder.Name = "Chevron"
    holder.BackgroundTransparency = 1
    holder.Size = UDim2.fromOffset(16, 16)
    holder.LayoutOrder = 99
    holder.Parent = parent

    local function bar(name, x, angle)
        local b = Instance.new("Frame")
        b.Name = name
        b.BackgroundColor3 = Theme.TextSub
        b.BorderSizePixel = 0
        b.AnchorPoint = Vector2.new(0.5, 0.5)
        b.Position = UDim2.fromOffset(x, 8)
        b.Size = UDim2.fromOffset(8, 2)
        b.Rotation = angle
        corner(b, 1)
        b.Parent = holder
        return b
    end
    local left = bar("L", 5, 45)
    local right = bar("R", 11, -45)

    -- A table, not fields on the Instance: Roblox objects reject new members.
    return {
        frame = holder,
        setOpen = function(open)
            left.Rotation = open and -45 or 45
            right.Rotation = open and 45 or -45
            local c = open and Theme.AccentMid or Theme.TextSub
            left.BackgroundColor3 = c
            right.BackgroundColor3 = c
        end,
    }
end

-- A control row: the base for everything with a label on the left.
-- `reserve` is how much room the right-hand controls need (their width plus
-- the gap), used only if UIFlexItem is unavailable.
local function row(parent, text, order, height, reserve)
    local r = Instance.new("Frame")
    r.Name = "Row"
    r.BackgroundColor3 = Theme.SurfaceElement
    r.BorderSizePixel = 0
    r.Size = UDim2.new(1, 0, 0, height or Theme.RowH)
    r.LayoutOrder = order or 1
    r.Parent = parent
    corner(r, Theme.RadiusMd)
    stroke(r, Theme.Hairline, 1)
    pad(r, 0, Theme.GapLg, 0, Theme.GapLg)
    local layout = hlist(r, Theme.GapMd)

    local l = label(r, text, "rowLabel", 1)
    l.Size = UDim2.new(1, 0, 1, 0)
    l.TextTruncate = Enum.TextTruncate.AtEnd
    -- The label takes the slack so the control sits hard right.
    flexFill(l, reserve or 24)

    return r, l, layout
end

-- Rows light up under the cursor, and a clickable row reports clicks on ITSELF.
--
-- This used to drop a full-width invisible TextButton into the row to catch the
-- click. That is what made every row label vanish in 2.7.0/2.7.1: a row has a
-- horizontal UIListLayout, the layout lays out ALL GuiObject children, and the
-- hit button was Size (1,1) scale at LayoutOrder 0 - so it sorted first, took
-- the whole width, and pushed the label and the control off the right-hand edge
-- where the window clipped them. Captions, buttons and list entries were fine
-- precisely because none of them go through row().
--
-- A Frame with Active = true raises InputBegan for mouse buttons on its own, so
-- no extra child is needed and nothing joins the layout.
local function hoverable(frame, clickable)
    -- Whatever the frame was painted is what it goes back to: section headers
    -- are darker than ordinary rows and must not come back as one.
    local base = frame.BackgroundColor3
    frame.MouseEnter:Connect(function() frame.BackgroundColor3 = Theme.SurfaceHover end)
    frame.MouseLeave:Connect(function() frame.BackgroundColor3 = base end)
    if not clickable then return nil end
    frame.Active = true
    return {
        onClick = function(fn)
            frame.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1
                    or input.UserInputType == Enum.UserInputType.Touch then
                    fn()
                end
            end)
        end,
    }
end

-- Toggle: 38x20, the knob slides and the track takes the accent when on.
local function toggle(parent, text, get, set, order, explain)
    local r, _, _ = row(parent, text, order, nil, 46)
    local hit = hoverable(r, true)

    local track = Instance.new("Frame")
    track.Name = "Track"
    track.BackgroundColor3 = Theme.SurfaceField
    track.BorderSizePixel = 0
    track.Size = UDim2.fromOffset(38, 20)
    track.LayoutOrder = 2
    track.Parent = r
    corner(track, 10)
    local trackStroke = stroke(track, Theme.Hairline, 1)
    local grad = accentGradient(track, 0)
    grad.Enabled = false

    local knob = Instance.new("Frame")
    knob.Name = "Knob"
    knob.BackgroundColor3 = Theme.TextMuted
    knob.BorderSizePixel = 0
    knob.Size = UDim2.fromOffset(14, 14)
    knob.Position = UDim2.fromOffset(2, 3)
    knob.ZIndex = 2
    corner(knob, 7)
    knob.Parent = track

    local function render()
        local on = get() and true or false
        grad.Enabled = on
        track.BackgroundColor3 = on and Color3.new(1, 1, 1) or Theme.SurfaceField
        trackStroke.Transparency = on and 1 or 0
        knob.BackgroundColor3 = on and Theme.TextOnAccent or Theme.TextMuted
        knob.Position = UDim2.fromOffset(on and 22 or 2, 3)
    end
    render()
    hit.onClick(function()
        set(not get())
        render()
    end)
    tip(r, explain)
    return { row = r, render = render }
end

-- A square toggle, for switching whole modules on and off. Deliberately a
-- different shape from the pill: a pill reads as a setting, and these are not
-- settings - they decide whether a thing exists on screen at all. On takes the
-- accent gradient, off greys out.
local function squareToggle(parent, text, get, set, order, explain)
    local r, _, _ = row(parent, text, order, nil, 32)
    local hit = hoverable(r, true)

    local box = Instance.new("Frame")
    box.Name = "Box"
    box.BackgroundColor3 = Color3.new(1, 1, 1)
    box.BorderSizePixel = 0
    box.Size = UDim2.fromOffset(24, 24)
    box.LayoutOrder = 2
    box.Parent = r
    corner(box, Theme.RadiusMd)
    local boxStroke = stroke(box, Theme.Hairline, 1)
    local grad = accentGradient(box, 45)

    local function render()
        local on = get() and true or false
        grad.Enabled = on
        box.BackgroundColor3 = on and Color3.new(1, 1, 1) or Theme.SurfaceField
        boxStroke.Color = on and Theme.AccentMid or Theme.Hairline
        boxStroke.Transparency = on and 1 or 0
    end
    render()
    hit.onClick(function()
        set(not get())
        render()
    end)
    tip(r, explain)
    return { row = r, render = render }
end

-- Slider: label + description, then an 18px track whose fill carries the
-- readout on its right edge, so the number always sits on the accent.
local function slider(parent, text, desc, minVal, maxVal, isFloat, get, set, order, explain)
    local holder = Instance.new("Frame")
    holder.Name = "Slider"
    holder.BackgroundTransparency = 1
    holder.AutomaticSize = Enum.AutomaticSize.Y
    holder.Size = UDim2.new(1, 0, 0, 0)
    holder.LayoutOrder = order or 1
    holder.Parent = parent
    vlist(holder, Theme.GapSm)

    local head = Instance.new("Frame")
    head.Name = "Head"
    head.BackgroundTransparency = 1
    head.AutomaticSize = Enum.AutomaticSize.Y
    head.Size = UDim2.new(1, 0, 0, 0)
    head.LayoutOrder = 1
    head.Parent = holder
    vlist(head, 1)

    local title = label(head, text, "rowLabel", 1)
    title.Size = UDim2.new(1, 0, 0, 18)
    if desc and desc ~= "" then
        local sub = label(head, desc, "captionSub", 2)
        sub.Size = UDim2.new(1, 0, 0, 12)
    end

    local track = Instance.new("Frame")
    track.Name = "Track"
    track.BackgroundColor3 = Theme.SurfaceField
    track.BorderSizePixel = 0
    track.Size = UDim2.new(1, 0, 0, 18)
    track.ClipsDescendants = true
    track.LayoutOrder = 2
    track.Active = true
    track.Parent = holder
    corner(track, Theme.RadiusSm)
    stroke(track, Theme.Hairline, 1)

    local fill = Instance.new("Frame")
    fill.Name = "Fill"
    fill.BackgroundColor3 = Color3.new(1, 1, 1)
    fill.BorderSizePixel = 0
    fill.Size = UDim2.fromScale(0, 1)
    fill.Parent = track
    corner(fill, Theme.RadiusSm)
    accentGradient(fill, 0)

    -- The readout rides the fill's right edge while there is room for it, and
    -- steps outside onto the dark remainder when the fill gets too short.
    local readout = Instance.new("TextLabel")
    readout.Name = "Value"
    readout.BackgroundTransparency = 1
    readout.Size = UDim2.new(1, -8, 1, 0)
    readout.Position = UDim2.fromOffset(0, 0)
    readout.TextXAlignment = Enum.TextXAlignment.Right
    readout.TextColor3 = Theme.TextOnAccent
    readout.TextSize = 11
    readout.ZIndex = 3
    setFont(readout, "mono", Enum.FontWeight.Medium)
    readout.Parent = fill

    local function format(value)
        if isFloat then return string.format("%.1f", value) end
        return tostring(math.floor(value + 0.5))
    end

    local function render()
        local value = get()
        local alpha = math.clamp((value - minVal) / (maxVal - minVal), 0, 1)
        fill.Size = UDim2.fromScale(alpha, 1)
        readout.Text = format(value)
        if alpha < 0.22 then
            -- Outside the fill, in primary, per the design note.
            readout.Parent = track
            readout.Size = UDim2.new(1, -8, 1, 0)
            readout.TextColor3 = Theme.TextPrimary
        else
            readout.Parent = fill
            readout.Size = UDim2.new(1, -8, 1, 0)
            readout.TextColor3 = Theme.TextOnAccent
        end
    end
    render()

    local dragging = false
    local function setFromX(x)
        if track.AbsoluteSize.X <= 0 then return end
        local alpha = math.clamp((x - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1)
        local value = minVal + (maxVal - minVal) * alpha
        if isFloat then
            value = math.floor(value * 10 + 0.5) / 10
        else
            value = math.floor(value + 0.5)
        end
        set(value)
        render()
    end
    track.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            setFromX(input.Position.X)
        end
    end)
    table.insert(S.sliderConnections, UserInputService.InputChanged:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch) then
            setFromX(input.Position.X)
        end
    end))
    table.insert(S.sliderConnections, UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
        end
    end))

    tip(holder, explain)
    return { holder = holder, render = render }
end

-- Dropdown row: the current value, a chevron, and a list that drops under it.
local function dropdown(parent, text, options, get, set, order, explain)
    local holder = Instance.new("Frame")
    holder.Name = "Dropdown"
    holder.BackgroundTransparency = 1
    holder.AutomaticSize = Enum.AutomaticSize.Y
    holder.Size = UDim2.new(1, 0, 0, 0)
    holder.LayoutOrder = order or 1
    holder.Parent = parent
    vlist(holder, 4)

    local r, _, _ = row(holder, text, 1, nil, 90)
    local hit = hoverable(r, true)

    local value = label(r, "", "captionKey", 2)
    value.Size = UDim2.fromOffset(0, 18)
    value.AutomaticSize = Enum.AutomaticSize.X
    value.TextXAlignment = Enum.TextXAlignment.Right

    local chev = chevron(r)

    local menu = Instance.new("Frame")
    menu.Name = "Menu"
    menu.BackgroundColor3 = Theme.SurfaceField
    menu.BorderSizePixel = 0
    menu.AutomaticSize = Enum.AutomaticSize.Y
    menu.Size = UDim2.new(1, 0, 0, 0)
    menu.Visible = false
    menu.LayoutOrder = 2
    menu.Parent = holder
    corner(menu, Theme.RadiusMd)
    stroke(menu, Theme.Hairline, 1)
    pad(menu, 4, 4, 4, 4)
    vlist(menu, 2)

    local optionButtons = {}
    local function render()
        local current = get()
        value.Text = tostring(current)
        for optValue, button in pairs(optionButtons) do
            local on = optValue == current
            button.BackgroundColor3 = on and Theme.SurfaceHover or Theme.SurfaceElement
            button.TextColor3 = on and Theme.AccentMid or Theme.TextSub
        end
    end

    for i, option in ipairs(options) do
        local b = Instance.new("TextButton")
        b.Name = tostring(option.value)
        b.BackgroundColor3 = Theme.SurfaceElement
        b.BorderSizePixel = 0
        b.Size = UDim2.new(1, 0, 0, 26)
        b.Text = option.label or tostring(option.value)
        b.TextColor3 = Theme.TextSub
        b.TextSize = 12
        b.LayoutOrder = i
        setFont(b, "sans", Enum.FontWeight.Medium)
        b.Parent = menu
        corner(b, 4)
        b.MouseButton1Click:Connect(function()
            set(option.value)
            menu.Visible = false
            chev.setOpen(false)
            render()
        end)
        optionButtons[option.value] = b
    end
    render()

    hit.onClick(function()
        menu.Visible = not menu.Visible
        chev.setOpen(menu.Visible)
    end)
    -- Clicking an option closes the menu; keep the chevron honest.
    render()
    tip(r, explain)
    return { holder = holder, render = render }
end

-- A small right-aligned number field on a row.
local function numberBox(parent, text, get, set, order, explain)
    local r, _, _ = row(parent, text, order, nil, 69)

    local box = Instance.new("TextBox")
    box.Name = "Value"
    box.BackgroundColor3 = Theme.SurfaceField
    box.BorderSizePixel = 0
    box.Size = UDim2.fromOffset(61, 20)
    box.LayoutOrder = 2
    box.Text = tostring(get())
    box.TextColor3 = Theme.TextSub
    box.TextSize = 12
    box.TextXAlignment = Enum.TextXAlignment.Right
    box.ClearTextOnFocus = false
    box.ClipsDescendants = true
    setFont(box, "sans", Enum.FontWeight.Medium)
    box.Parent = r
    corner(box, Theme.RadiusSm)
    stroke(box, Theme.Hairline, 1)
    pad(box, 0, 8, 0, 6)

    local function render() box.Text = tostring(get()) end
    box.FocusLost:Connect(function()
        local n = tonumber(box.Text)
        if n then set(n) end
        render()
    end)
    tip(r, explain)
    return { row = r, render = render }
end

-- Swatch + colour picker. The SV square is one frame with two stacked fills -
-- white to hue horizontally, clear to black vertically - exactly as the design
-- describes; changing the hue only touches the first gradient's second stop.
local function colorRow(parent, text, get, set, order, explain)
    local holder = Instance.new("Frame")
    holder.Name = "Color"
    holder.BackgroundTransparency = 1
    holder.AutomaticSize = Enum.AutomaticSize.Y
    holder.Size = UDim2.new(1, 0, 0, 0)
    holder.LayoutOrder = order or 1
    holder.Parent = parent
    vlist(holder, Theme.GapSm)

    local r, _, _ = row(holder, text, 1, nil, 54)
    local hit = hoverable(r, true)

    local swatch = Instance.new("Frame")
    swatch.Name = "Swatch"
    swatch.BackgroundColor3 = get()
    swatch.BorderSizePixel = 0
    swatch.Size = UDim2.fromOffset(46, 20)
    swatch.LayoutOrder = 2
    swatch.Parent = r
    corner(swatch, Theme.RadiusSm)
    stroke(swatch, Theme.Hairline, 1)

    local picker = Instance.new("Frame")
    picker.Name = "Picker"
    picker.BackgroundTransparency = 1
    picker.Size = UDim2.new(1, 0, 0, 140)
    picker.Visible = false
    picker.LayoutOrder = 2
    picker.Parent = holder
    hlist(picker, Theme.GapMd)

    local sv = Instance.new("Frame")
    sv.Name = "SV"
    sv.BackgroundColor3 = Color3.new(1, 1, 1)
    sv.BorderSizePixel = 0
    sv.Size = UDim2.new(1, -22, 1, 0)
    sv.Active = true
    sv.LayoutOrder = 1
    sv.Parent = picker
    corner(sv, Theme.RadiusMd)
    flexFill(sv, 22)   -- the hue rail (14) plus the gap (8)

    local hueGradient = Instance.new("UIGradient")
    hueGradient.Rotation = 0
    hueGradient.Parent = sv

    local shade = Instance.new("Frame")
    shade.Name = "Shade"
    shade.BackgroundColor3 = Color3.new(0, 0, 0)
    shade.BorderSizePixel = 0
    shade.Size = UDim2.fromScale(1, 1)
    shade.Parent = sv
    corner(shade, Theme.RadiusMd)
    local shadeGradient = Instance.new("UIGradient")
    shadeGradient.Rotation = 90
    shadeGradient.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 1),
        NumberSequenceKeypoint.new(1, 0),
    })
    shadeGradient.Parent = shade

    local cursor = Instance.new("Frame")
    cursor.Name = "Cursor"
    cursor.BackgroundTransparency = 1
    cursor.AnchorPoint = Vector2.new(0.5, 0.5)
    cursor.Size = UDim2.fromOffset(12, 12)
    cursor.ZIndex = 4
    cursor.Parent = sv
    corner(cursor, 6)
    stroke(cursor, Color3.new(1, 1, 1), 2)

    local hue = Instance.new("Frame")
    hue.Name = "Hue"
    hue.BackgroundColor3 = Color3.new(1, 1, 1)
    hue.BorderSizePixel = 0
    hue.Size = UDim2.new(0, 14, 1, 0)
    hue.Active = true
    hue.LayoutOrder = 2
    hue.Parent = picker
    corner(hue, Theme.RadiusSm)
    local rail = Instance.new("UIGradient")
    rail.Rotation = 90
    rail.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0.00, Color3.fromRGB(255, 0, 0)),
        ColorSequenceKeypoint.new(0.17, Color3.fromRGB(255, 255, 0)),
        ColorSequenceKeypoint.new(0.33, Color3.fromRGB(0, 255, 0)),
        ColorSequenceKeypoint.new(0.50, Color3.fromRGB(0, 255, 255)),
        ColorSequenceKeypoint.new(0.67, Color3.fromRGB(0, 0, 255)),
        ColorSequenceKeypoint.new(0.83, Color3.fromRGB(255, 0, 255)),
        ColorSequenceKeypoint.new(1.00, Color3.fromRGB(255, 0, 0)),
    })
    rail.Parent = hue

    local marker = Instance.new("Frame")
    marker.Name = "Marker"
    marker.BackgroundColor3 = Color3.new(1, 1, 1)
    marker.BorderSizePixel = 0
    marker.AnchorPoint = Vector2.new(0.5, 0.5)
    marker.Size = UDim2.fromOffset(20, 3)
    marker.Position = UDim2.new(0.5, 0, 0, 0)
    marker.ZIndex = 4
    corner(marker, 2)
    marker.Parent = hue

    local h, s, v = get():ToHSV()

    local function apply()
        local color = Color3.fromHSV(h, s, v)
        swatch.BackgroundColor3 = color
        hueGradient.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromHSV(h, 1, 1))
        cursor.Position = UDim2.fromScale(s, 1 - v)
        marker.Position = UDim2.new(0.5, 0, h, 0)
        set(color)
    end
    apply()

    local draggingSV, draggingHue = false, false
    local function svFromPosition(x, y)
        if sv.AbsoluteSize.X <= 0 then return end
        s = math.clamp((x - sv.AbsolutePosition.X) / sv.AbsoluteSize.X, 0, 1)
        v = 1 - math.clamp((y - sv.AbsolutePosition.Y) / sv.AbsoluteSize.Y, 0, 1)
        apply()
    end
    local function hueFromPosition(y)
        if hue.AbsoluteSize.Y <= 0 then return end
        h = math.clamp((y - hue.AbsolutePosition.Y) / hue.AbsoluteSize.Y, 0, 1)
        apply()
    end

    sv.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            draggingSV = true
            svFromPosition(input.Position.X, input.Position.Y)
        end
    end)
    hue.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            draggingHue = true
            hueFromPosition(input.Position.Y)
        end
    end)
    table.insert(S.sliderConnections, UserInputService.InputChanged:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then return end
        if draggingSV then svFromPosition(input.Position.X, input.Position.Y) end
        if draggingHue then hueFromPosition(input.Position.Y) end
    end))
    table.insert(S.sliderConnections, UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            draggingSV, draggingHue = false, false
        end
    end))

    hit.onClick(function()
        picker.Visible = not picker.Visible
    end)
    tip(r, explain)
    return { holder = holder, render = apply }
end

-- Button. "accent" is the primary action; "ghost" is the in-section default.
local function button(parent, text, style, onClick, order, explain)
    local b = Instance.new("TextButton")
    b.Name = "Button"
    b.BorderSizePixel = 0
    b.Size = UDim2.new(1, 0, 0, 32)
    b.Text = text
    b.TextSize = 13
    b.AutoButtonColor = false
    b.LayoutOrder = order or 1
    setFont(b, "sans", Enum.FontWeight.SemiBold)
    b.Parent = parent
    corner(b, Theme.RadiusMd)

    if style == "accent" then
        b.BackgroundColor3 = Color3.new(1, 1, 1)
        b.TextColor3 = Theme.TextOnAccent
        accentGradient(b, 0)
    elseif style == "danger" then
        b.BackgroundColor3 = Theme.StatusBad
        -- Dark on the red, as the design has it. #ff6060 is light enough that
        -- dark type has more contrast on it than white does.
        b.TextColor3 = Theme.TextOnAccent
    else
        b.BackgroundColor3 = Theme.SurfaceElement
        b.TextColor3 = Theme.TextPrimary
        stroke(b, Theme.Hairline, 1)
        b.MouseEnter:Connect(function() b.BackgroundColor3 = Theme.SurfaceHover end)
        b.MouseLeave:Connect(function() b.BackgroundColor3 = Theme.SurfaceElement end)
    end

    if onClick then b.MouseButton1Click:Connect(onClick) end
    tip(b, explain)
    return b
end

-- A horizontal strip of equal-width buttons.
local function buttonRow(parent, order)
    local holder = Instance.new("Frame")
    holder.Name = "Buttons"
    holder.BackgroundTransparency = 1
    holder.Size = UDim2.new(1, 0, 0, 32)
    holder.LayoutOrder = order or 1
    holder.Parent = parent
    hlist(holder, Theme.GapMd)

    local count = 0
    local buttons = {}
    -- Equal widths without UIFlexItem would need to know the final count up
    -- front, so the fallback re-sizes every sibling as each one is added.
    local api = { frame = holder }
    function api.add(text, style, onClick, explain)
        count = count + 1
        local b = button(holder, text, style, onClick, count, explain)
        b.Size = UDim2.new(0, 0, 1, 0)
        buttons[count] = b
        -- Equal widths, recomputed as each button is added.
        for _, sibling in ipairs(buttons) do
            sibling.Size = UDim2.new(1 / count, -(Theme.GapMd * (count - 1)) / count, 1, 0)
        end
        return b
    end
    return api
end

-- The add-an-entry field. The round confirm is the only round thing in the
-- kit, deliberately: it reads as the commit action.
local function textField(parent, placeholder, onSubmit, order, explain)
    local holder = Instance.new("Frame")
    holder.Name = "TextField"
    holder.BackgroundTransparency = 1
    holder.Size = UDim2.new(1, 0, 0, 30)
    holder.LayoutOrder = order or 1
    holder.Parent = parent
    hlist(holder, Theme.GapMd)

    local box = Instance.new("TextBox")
    box.Name = "Input"
    box.BackgroundColor3 = Theme.SurfaceField
    box.BorderSizePixel = 0
    box.Size = UDim2.new(1, -36, 1, 0)
    box.Text = ""
    box.PlaceholderText = placeholder or ""
    box.PlaceholderColor3 = Theme.TextMuted
    box.TextColor3 = Theme.TextPrimary
    box.TextSize = 12
    box.TextXAlignment = Enum.TextXAlignment.Left
    box.ClearTextOnFocus = false
    box.ClipsDescendants = true
    box.LayoutOrder = 1
    setFont(box, "sans", Enum.FontWeight.Medium)
    box.Parent = holder
    corner(box, Theme.RadiusMd)
    stroke(box, Theme.Hairline, 1)
    pad(box, 0, 10, 0, 10)
    flexFill(box, 36)   -- the confirm button (28) plus the gap (8)

    local confirm = Instance.new("TextButton")
    confirm.Name = "Confirm"
    confirm.BackgroundColor3 = Color3.new(1, 1, 1)
    confirm.BorderSizePixel = 0
    confirm.Size = UDim2.fromOffset(28, 28)
    confirm.Text = ""
    confirm.AutoButtonColor = false
    confirm.LayoutOrder = 2
    confirm.Parent = holder
    corner(confirm, 14)
    accentGradient(confirm, 45)

    -- Tick, from two bars.
    local function bar(w, h, x, y, angle)
        local f = Instance.new("Frame")
        f.BackgroundColor3 = Theme.TextOnAccent
        f.BorderSizePixel = 0
        f.AnchorPoint = Vector2.new(0.5, 0.5)
        f.Size = UDim2.fromOffset(w, h)
        f.Position = UDim2.fromOffset(x, y)
        f.Rotation = angle
        f.ZIndex = 2
        corner(f, 1)
        f.Parent = confirm
    end
    bar(2, 7, 11, 17, -45)
    bar(2, 12, 16, 13, 35)

    local function submit()
        local text = box.Text:gsub("^%s+", ""):gsub("%s+$", "")
        if text == "" then return end
        box.Text = ""
        onSubmit(text)
    end
    confirm.MouseButton1Click:Connect(submit)
    box.FocusLost:Connect(function(enter) if enter then submit() end end)
    tip(confirm, explain)
    return { holder = holder, box = box }
end

-- A bordered, scrolling container for list entries.
local function list(parent, height, order)
    local holder = Instance.new("Frame")
    holder.Name = "List"
    holder.BackgroundColor3 = Theme.SurfaceField
    holder.BorderSizePixel = 0
    holder.Size = UDim2.new(1, 0, 0, height or 160)
    holder.LayoutOrder = order or 1
    holder.Parent = parent
    corner(holder, Theme.RadiusMd)
    stroke(holder, Theme.Hairline, 1)

    local scroll = Instance.new("ScrollingFrame")
    scroll.Name = "Scroll"
    scroll.BackgroundTransparency = 1
    scroll.BorderSizePixel = 0
    scroll.Size = UDim2.fromScale(1, 1)
    scroll.CanvasSize = UDim2.new()
    scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
    scroll.ScrollBarThickness = 4
    scroll.ScrollBarImageColor3 = Color3.fromHex("50505f")
    scroll.Parent = holder
    pad(scroll, 6, 6, 6, 6)
    vlist(scroll, Theme.GapSm)
    return scroll
end

-- One list entry: title / meta on the left, actions on the right.
-- One list entry: title over meta on the left, actions on the right.
--
-- Explicit positions, no inner layout. This used to be a horizontal list
-- holding a frame that held a vertical list, and nested auto-layout has now
-- mangled two different things in this GUI (the HUD came apart, row labels were
-- pushed off screen). Two labels and a row of icons do not need a layout engine
-- to place them.
local function listEntry(parent, title, meta, order, actionCount, height, accent)
    local n = actionCount or 2
    local actionsWidth = n * 24 + math.max(n - 1, 0) * 2
    local h = height or 46

    local e = Instance.new("Frame")
    e.Name = "Entry"
    e.BackgroundColor3 = Theme.SurfaceElement
    e.BorderSizePixel = 0
    e.Size = UDim2.new(1, 0, 0, h)
    e.LayoutOrder = order or 1
    e.ClipsDescendants = true
    e.Parent = parent
    corner(e, Theme.RadiusSm)
    stroke(e, Theme.Hairline, 1)

    -- With an accent, a colour bar runs down the left edge and the text moves
    -- over to make room; this is how a list entry says "the cyan one".
    local textX = 10
    if accent then
        local bar = Instance.new("Frame")
        bar.Name = "Accent"
        bar.BackgroundColor3 = accent
        bar.BorderSizePixel = 0
        bar.Size = UDim2.new(0, 5, 1, 0)
        bar.Parent = e
        textX = 16
    end
    local textWidth = -(textX + actionsWidth + 16)

    local titleLabel = label(e, title, "rowEntry", 1)
    titleLabel.Position = UDim2.fromOffset(textX, 5)
    titleLabel.Size = UDim2.new(1, textWidth, 0, 17)
    titleLabel.TextTruncate = Enum.TextTruncate.AtEnd

    local metaLabel = label(e, meta or "", "monoMeta", 2)
    metaLabel.Position = UDim2.fromOffset(textX, 24)
    metaLabel.Size = UDim2.new(1, textWidth, 0, 14)
    metaLabel.TextTruncate = Enum.TextTruncate.AtEnd

    local actions = Instance.new("Frame")
    actions.Name = "Actions"
    actions.BackgroundTransparency = 1
    actions.AnchorPoint = Vector2.new(1, 0.5)
    actions.Position = UDim2.new(1, -8, 0.5, 0)
    actions.Size = UDim2.fromOffset(actionsWidth, 24)
    actions.Parent = e
    hlist(actions, 2)

    return { frame = e, title = titleLabel, meta = metaLabel, actions = actions }
end

-- Row action icons, drawn from rectangles: no asset to fail to load.
local function iconButton(parent, kind, onClick, order, explain)
    local b = Instance.new("TextButton")
    b.Name = kind
    b.BackgroundColor3 = Theme.SurfaceHover
    b.BackgroundTransparency = 1
    b.BorderSizePixel = 0
    b.Size = UDim2.fromOffset(24, 24)
    b.Text = ""
    b.AutoButtonColor = false
    b.LayoutOrder = order or 1
    b.Parent = parent
    corner(b, Theme.RadiusSm)
    b.MouseEnter:Connect(function() b.BackgroundTransparency = 0.7 end)
    b.MouseLeave:Connect(function() b.BackgroundTransparency = 1 end)

    local function piece(color, w, h, x, y, angle, radius)
        local f = Instance.new("Frame")
        f.BackgroundColor3 = color
        f.BorderSizePixel = 0
        f.AnchorPoint = Vector2.new(0.5, 0.5)
        f.Size = UDim2.fromOffset(w, h)
        f.Position = UDim2.fromOffset(x, y)
        f.Rotation = angle or 0
        f.ZIndex = 2
        if radius then corner(f, radius) end
        f.Parent = b
        return f
    end

    if kind == "edit" then
        piece(Theme.AccentMid, 3, 12, 13, 11, 45, 1)
        piece(Theme.AccentMid, 3, 3, 8, 17, 45)
    elseif kind == "delete" then
        piece(Theme.StatusBad, 11, 2, 12, 7, 0, 1)
        piece(Theme.StatusBad, 9, 9, 12, 14, 0, 2)
    elseif kind == "up" then
        piece(Theme.TextSub, 7, 2, 10, 13, 45, 1)
        piece(Theme.TextSub, 7, 2, 14, 13, -45, 1)
    elseif kind == "down" then
        piece(Theme.TextSub, 7, 2, 10, 11, -45, 1)
        piece(Theme.TextSub, 7, 2, 14, 11, 45, 1)
    elseif kind == "play" then
        piece(Theme.StatusGood, 3, 10, 10, 12, 0, 1)
        piece(Theme.StatusGood, 3, 10, 14, 12, 0, 1)
    elseif kind == "check" then
        piece(Theme.StatusGood, 3, 7, 9, 14, -45, 1)
        piece(Theme.StatusGood, 3, 13, 14, 11, 45, 1)
    elseif kind == "cross" then
        piece(Theme.StatusBad, 3, 14, 12, 12, 45, 1)
        piece(Theme.StatusBad, 3, 14, 12, 12, -45, 1)
    end

    if onClick then b.MouseButton1Click:Connect(onClick) end
    tip(b, explain)
    return b
end

-- =========================================================================
-- Window and section
-- =========================================================================

local function makeDraggable(handle, target)
    local dragging, startPos, startOffset = false, nil, nil
    handle.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            startPos = input.Position
            startOffset = target.Position
        end
    end)
    handle.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
        end
    end)
    table.insert(S.sliderConnections, UserInputService.InputChanged:Connect(function(input)
        if not dragging then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then return end
        local delta = input.Position - startPos
        target.Position = UDim2.new(
            startOffset.X.Scale, startOffset.X.Offset + delta.X,
            startOffset.Y.Scale, startOffset.Y.Offset + delta.Y)
    end))
end

-- A window: accent bar, header (drag handle, accent tile, title, optional ⓘ),
-- hairline divider, then a scrolling body. The body scrolls because a full
-- accordion is taller than a 768p screen, which is the one thing a fixed
-- height would get wrong on half the machines this runs on.
local function window(parent, opts)
    local frame = Instance.new("Frame")
    frame.Name = opts.name or "Window"
    frame.BackgroundColor3 = Color3.new(1, 1, 1)
    frame.BorderSizePixel = 0
    frame.Size = UDim2.fromOffset(opts.width or 310, opts.height or 460)
    frame.Position = opts.position or UDim2.fromOffset(40, 40)
    frame.Visible = opts.visible ~= false
    frame.Active = true
    frame.ClipsDescendants = true
    frame.ZIndex = 2
    frame.Parent = parent
    corner(frame, Theme.RadiusLg)
    stroke(frame, Theme.Hairline, 1)
    bodyGradient(frame)
    shadow(frame)

    local accent = Instance.new("Frame")
    accent.Name = "AccentBar"
    accent.BackgroundColor3 = Color3.new(1, 1, 1)
    accent.BorderSizePixel = 0
    accent.Size = UDim2.new(1, 0, 0, 3)
    accent.ZIndex = 3
    accent.Parent = frame
    accentGradient(accent, 0)

    local header = Instance.new("Frame")
    header.Name = "Header"
    header.BackgroundColor3 = Theme.SurfaceHeader
    header.BorderSizePixel = 0
    header.Size = UDim2.new(1, 0, 0, Theme.HeaderH)
    header.Position = UDim2.fromOffset(0, 3)
    header.Active = true
    header.ZIndex = 3
    header.Parent = frame
    pad(header, 0, 12, 0, 14)
    hlist(header, Theme.GapLg)
    makeDraggable(header, frame)

    local tile = Instance.new("Frame")
    tile.Name = "Icon"
    tile.BackgroundColor3 = Color3.new(1, 1, 1)
    tile.BorderSizePixel = 0
    tile.Size = UDim2.fromOffset(14, 14)
    tile.LayoutOrder = 1
    tile.ZIndex = 4
    tile.Parent = header
    corner(tile, 4)
    accentGradient(tile, 45)

    local title = label(header, opts.title or "Window", "windowTitle", 2)
    title.ZIndex = 4
    -- tile (14) + gap (12), the pin (20) + gap (12), and the info circle
    -- (20) + gap (12) when there is one.
    flexFill(title, 26 + 32 + (opts.info and 32 or 0))

    -- The pin. A pinned window stays on screen after the interface is closed,
    -- so a readout you want while you play does not cost you the whole GUI.
    -- Grey when it is not pinned, accent when it is.
    local pinned = false
    local pin = Instance.new("TextButton")
    pin.Name = "Pin"
    pin.BackgroundColor3 = Theme.SurfaceElement
    pin.BorderSizePixel = 0
    pin.Size = UDim2.fromOffset(20, 20)
    pin.Text = ""
    pin.AutoButtonColor = false
    pin.LayoutOrder = 3
    pin.ZIndex = 4
    pin.Parent = header
    corner(pin, 6)
    local pinStroke = stroke(pin, Theme.Hairline, 1)

    -- A thumbtack, drawn from two frames: no asset to fail to load.
    local pinHead = Instance.new("Frame")
    pinHead.Name = "Head"
    pinHead.BorderSizePixel = 0
    pinHead.AnchorPoint = Vector2.new(0.5, 0.5)
    pinHead.Position = UDim2.fromOffset(10, 7)
    pinHead.Size = UDim2.fromOffset(11, 4)
    pinHead.ZIndex = 5
    corner(pinHead, 2)
    pinHead.Parent = pin

    local pinStem = Instance.new("Frame")
    pinStem.Name = "Stem"
    pinStem.BorderSizePixel = 0
    pinStem.AnchorPoint = Vector2.new(0.5, 0)
    pinStem.Position = UDim2.fromOffset(10, 9)
    pinStem.Size = UDim2.fromOffset(3, 7)
    pinStem.ZIndex = 5
    corner(pinStem, 1)
    pinStem.Parent = pin

    local function renderPin()
        local color = pinned and Theme.AccentMid or Theme.TextMuted
        pinHead.BackgroundColor3 = color
        pinStem.BackgroundColor3 = color
        pinStroke.Color = pinned and Theme.AccentMid or Theme.Hairline
        pin.BackgroundColor3 = pinned and Theme.SurfaceHover or Theme.SurfaceElement
    end
    renderPin()
    tip(pin, "Pin this window so it stays on screen after you close the interface. You can still drag it. Click again to let it hide with the rest.")

    if opts.info then
        local info = Instance.new("TextLabel")
        info.Name = "Info"
        info.BackgroundColor3 = Theme.SurfaceElement
        info.BorderSizePixel = 0
        info.Size = UDim2.fromOffset(20, 20)
        info.Text = "i"
        info.TextColor3 = Theme.TextSub
        info.TextSize = 12
        info.LayoutOrder = 3
        info.ZIndex = 4
        setFont(info, "sans", Enum.FontWeight.Bold)
        info.Parent = header
        corner(info, 10)
        stroke(info, Theme.Hairline, 1)
        tip(info, opts.info)
    end

    local divider = Instance.new("Frame")
    divider.Name = "Divider"
    divider.BackgroundColor3 = Theme.Hairline
    divider.BorderSizePixel = 0
    divider.Size = UDim2.new(1, 0, 0, 1)
    divider.Position = UDim2.fromOffset(0, 3 + Theme.HeaderH)
    divider.ZIndex = 3
    divider.Parent = frame

    local body = Instance.new("ScrollingFrame")
    body.Name = "Body"
    body.BackgroundTransparency = 1
    body.BorderSizePixel = 0
    body.Position = UDim2.fromOffset(0, 4 + Theme.HeaderH)
    body.Size = UDim2.new(1, 0, 1, -(4 + Theme.HeaderH))
    body.CanvasSize = UDim2.new()
    body.AutomaticCanvasSize = Enum.AutomaticSize.Y
    body.ScrollBarThickness = 4
    body.ScrollBarImageColor3 = Color3.fromHex("50505f")
    body.ZIndex = 3
    body.Parent = frame
    pad(body, 10, Theme.GapLg, Theme.GapXl, Theme.GapLg)
    vlist(body, Theme.GapSm)

    local api = { frame = frame, header = header, body = body, title = title }

    function api.isPinned() return pinned end
    function api.setPinned(value)
        pinned = value and true or false
        renderPin()
        if opts.onPinChanged then opts.onPinChanged(api) end
    end
    pin.MouseButton1Click:Connect(function() api.setPinned(not pinned) end)

    return api
end

-- A collapsible section: the Row is the header, the content sits under it and
-- the whole thing grows with what is inside.
local function section(parent, title, order, explain)
    local holder = Instance.new("Frame")
    holder.Name = "Section"
    holder.BackgroundTransparency = 1
    holder.AutomaticSize = Enum.AutomaticSize.Y
    holder.Size = UDim2.new(1, 0, 0, 0)
    holder.LayoutOrder = order or 1
    holder.Parent = parent
    vlist(holder, Theme.GapSm)

    local head, headLabel, _ = row(holder, title, 1, nil, 24)
    head.BackgroundColor3 = Theme.SurfaceSection
    local hit = hoverable(head, true)
    local chev = chevron(head)

    -- The rows of an open section sit in a well a shade darker than the
    -- window, so the settings read as cards inside the list they belong to.
    local content = Instance.new("Frame")
    content.Name = "Content"
    content.BackgroundColor3 = Theme.SurfaceWell
    content.BorderSizePixel = 0
    content.AutomaticSize = Enum.AutomaticSize.Y
    content.Size = UDim2.new(1, 0, 0, 0)
    content.Visible = false
    content.LayoutOrder = 2
    content.Parent = holder
    corner(content, Theme.RadiusMd)
    vlist(content, Theme.GapSm)
    pad(content, 6, 6, 6, 6)

    local open = false
    local function setOpen(value)
        open = value and true or false
        content.Visible = open
        chev.setOpen(open)
        headLabel.TextColor3 = open and Theme.AccentMid or Theme.TextPrimary
    end
    setOpen(false)
    hit.onClick(function() setOpen(not open) end)
    tip(head, explain)

    return { holder = holder, content = content, setOpen = setOpen, isOpen = function() return open end }
end

-- A segmented control - the "island" at the top of a window. Exactly one of
-- the options is live, and picking one is a mode switch, not a setting: the
-- sections below it change with the choice.
local function segmented(parent, options, get, set, order, explain)
    local holder = Instance.new("Frame")
    holder.Name = "Segmented"
    holder.BackgroundColor3 = Theme.SurfaceField
    holder.BorderSizePixel = 0
    holder.Size = UDim2.new(1, 0, 0, 34)
    holder.LayoutOrder = order or 1
    holder.Parent = parent
    corner(holder, Theme.RadiusMd)
    stroke(holder, Theme.Hairline, 1)
    pad(holder, 3, 3, 3, 3)
    hlist(holder, 3)

    local buttons = {}
    local render

    for i, option in ipairs(options) do
        local b = Instance.new("TextButton")
        b.Name = tostring(option.value)
        b.BackgroundColor3 = Theme.SurfaceField
        b.BackgroundTransparency = 1
        b.BorderSizePixel = 0
        b.Size = UDim2.new(1 / #options, -(3 * (#options - 1)) / #options, 1, 0)
        b.Text = option.label or tostring(option.value)
        b.TextSize = 12
        b.AutoButtonColor = false
        b.LayoutOrder = i
        setFont(b, "sans", Enum.FontWeight.SemiBold)
        b.Parent = holder
        corner(b, Theme.RadiusSm)
        accentGradient(b, 0).Enabled = false
        buttons[option.value] = b
        tip(b, option.tip)
        b.MouseButton1Click:Connect(function()
            set(option.value)
            render()
        end)
    end

    render = function()
        local current = get()
        for value, b in pairs(buttons) do
            local on = value == current
            local grad = b:FindFirstChildOfClass("UIGradient")
            if grad then grad.Enabled = on end
            b.BackgroundTransparency = on and 0 or 1
            b.BackgroundColor3 = on and Color3.new(1, 1, 1) or Theme.SurfaceField
            b.TextColor3 = on and Theme.TextOnAccent or Theme.TextSub
        end
    end
    render()
    tip(holder, explain)
    return { holder = holder, render = render }
end

-- A plain hairline, used to fence off the master toggle at the top of a window.
local function separator(parent, order)
    local line = Instance.new("Frame")
    line.Name = "Separator"
    line.BackgroundColor3 = Theme.Hairline
    line.BorderSizePixel = 0
    line.Size = UDim2.new(1, 0, 0, 1)
    line.LayoutOrder = order or 1
    line.Parent = parent
    return line
end

-- A caption line, for the notes under a group of controls.
local function caption(parent, text, order)
    local l = label(parent, text, "captionSub", order)
    l.AutomaticSize = Enum.AutomaticSize.Y
    l.Size = UDim2.new(1, 0, 0, 0)
    l.TextWrapped = true
    l.TextYAlignment = Enum.TextYAlignment.Top
    return l
end

S.UIKit = {
    Theme = Theme,
    setFont = setFont, corner = corner, stroke = stroke, pad = pad,
    vlist = vlist, hlist = hlist, label = label, caption = caption, flexFill = flexFill,
    accentGradient = accentGradient, bodyGradient = bodyGradient, shadow = shadow,
    ensureTip = ensureTip, tip = tip, hideTip = hideTip,
    chevron = chevron, row = row, hoverable = hoverable,
    toggle = toggle, squareToggle = squareToggle, slider = slider, dropdown = dropdown, numberBox = numberBox,
    colorRow = colorRow, button = button, buttonRow = buttonRow,
    textField = textField, list = list, listEntry = listEntry, iconButton = iconButton,
    window = window, section = section, separator = separator, segmented = segmented,
    makeDraggable = makeDraggable,
}
end
    end)()
    module(S)
end

-- ===================================== src/reader.lua =====================================
do
    local module = (function()
-- reader.lua - Everything that can hurt, as boxes with live windows.
-- Module contract: receives the shared table S; imports from core only.
--
-- Four sources, one shape. A hazard is an oriented box (cframe, size) that
-- hurts from `from` until `until` on os.clock(). A moving hazard also carries a
-- flat velocity and its box is swept along it. The field never asks what a
-- thing is; it asks where and when.
--
--   Model attacks   hitBox (invisible damage volume) + precast (visible
--                   warning), parented to workspace. Timing by name from the
--                   seeds; a precast that fades means "fired", and fade plus a
--                   linger means "over" unless the seed says it burns on.
--   Bare parts      criss cross, strike meshes, orbs: a moving part is the box
--                   it sweeps over the next second. Faded and still = spent.
--   Boss remotes    scripted attacks announced with distance, duration,
--                   start/end on the game clock and an origin CFrame.
--   precastHitbox   the game's own ground telegraphs, exact impact time.
return function(S)
local CFG = S.CFG
local RT = S.RT
local TIMING = S.TIMING
local PROJECTILE_HINTS = S.PROJECTILE_HINTS
local Workspace = S.Workspace
local ReplicatedStorage = S.ReplicatedStorage
local Players = S.Players
local LocalPlayer = S.LocalPlayer
local heavyDebug = S.heavyDebug
local heavyDebugThrottled = S.heavyDebugThrottled
local isOurs = S.isOurs

local RD = {
    models = {},        -- [Model] = record
    parts = {},         -- [BasePart] = record (bare projectiles)
    zones = {},         -- announced: { cframe, size, from, until, moving? }
    enemies = {},       -- { model, root, humanoid, isBoss, melee, extent, x, z, vx, vz }
    connections = {},
    lastSweep = -math.huge,
    lastEnemyScan = -math.huge,
    timeSync = nil,
    count = 0,
    beams = {},         -- recent passive-beam spawns: { t, yaw, hub, size }
    fanUntil = -math.huge, -- the beam fan is on until this os.clock()
}

local lower = string.lower
local huge = math.huge

-- ------------------------------------------------------------ clocks
local function gameClock()
    local ts = RD.timeSync
    if ts then
        local ok, t = pcall(function() return ts:GetTime() end)
        if ok and type(t) == "number" then return t end
    end
    return Workspace:GetServerTimeNow()
end
-- A game-clock or server-clock time, as os.clock().
local function fromGame(t) return os.clock() + (t - gameClock()) end
local function fromServer(t) return os.clock() + (t - Workspace:GetServerTimeNow()) end

-- ------------------------------------------------------------ names
local function isProjectileName(name)
    local n = lower(name)
    for _, hint in ipairs(PROJECTILE_HINTS) do
        if n:find(hint, 1, true) then return true end
    end
    return false
end

local function findPart(model, ...)
    for _, name in ipairs({ ... }) do
        local p = model:FindFirstChild(name)
        if p and p:IsA("BasePart") then return p end
    end
    for _, d in ipairs(model:GetChildren()) do
        if d:IsA("BasePart") then
            local n = lower(d.Name)
            for _, name in ipairs({ ... }) do
                if n:find(lower(name), 1, true) then return d end
            end
        end
    end
    return nil
end

local function ownedByPlayer(inst)
    local node = inst
    for _ = 1, 4 do
        node = node and node.Parent
        if not node then break end
        if node:IsA("Model") and Players:GetPlayerFromCharacter(node) then return true end
    end
    return false
end

-- ------------------------------------------------------------ model attacks
local noteBeam
local function trackModel(model)
    if RD.models[model] or isOurs(model) or ownedByPlayer(model) then return end
    if model:FindFirstChildOfClass("Humanoid") then return end
    local hb = findPart(model, "hitBox", "hitbox")
    local pc = findPart(model, "precast", "preCast")
    if not hb and not pc then return end
    local name = lower(model.Name)
    local seed = TIMING[name]
    local now = os.clock()
    local first = seed and seed.first or (pc and CFG.defaultFire or 0)
    local last = seed and seed.last or (first + CFG.defaultLive)
    RD.models[model] = {
        model = model, hb = hb, pc = pc, name = name, spawn = now,
        from = now + first, untilAt = now + last, long = seed ~= nil and seed.long == true,
        minT = pc and pc.Transparency or 1, fired = false,
    }
    RD.count = RD.count + 1
    if hb and name:find("passivebeam", 1, true) then noteBeam(hb, now) end
end

local function trackPart(part)
    if RD.parts[part] or RD.models[part.Parent] or isOurs(part) or ownedByPlayer(part) then return end
    if not part:IsA("BasePart") then return end
    if not isProjectileName(part.Name) then return end
    local p = part.Position
    RD.parts[part] = { part = part, x = p.X, z = p.Z, vx = 0, vz = 0, at = os.clock(), spawn = os.clock() }
end

local function consider(inst)
    if inst:IsA("Model") then
        trackModel(inst)
    elseif inst:IsA("BasePart") then
        if inst.Parent == Workspace then
            trackPart(inst)
        else
            local model = inst:FindFirstAncestorOfClass("Model")
            if model and (inst.Name:lower():find("hitbox", 1, true) or inst.Name:lower():find("precast", 1, true)) then
                trackModel(model)
            end
        end
    end
end

-- ------------------------------------------------------------ boss remotes
local function addZone(z)
    RD.zones[#RD.zones + 1] = z
    if #RD.zones > 96 then table.remove(RD.zones, 1) end
end

-- The Champion's passive beams (8 x 250 through the hub, lethal from the
-- moment they appear) come in two rhythms. Slow: one every half second,
-- each 20 degrees on from the last - a sweep, so the next two lanes are
-- known and go in as zones. Fast: eighteen a second for seven seconds with
-- shifting offsets - a fan nothing inside 125 studs survives; the brain backs
-- out past the beams' reach while RD.fanUntil holds.
local function wrap180(a) a = a % 180 if a > 90 then a = a - 180 end return a end
noteBeam = function(hb, now)
    local look = hb.CFrame.LookVector
    local yaw = math.deg(math.atan2(look.X, look.Z)) % 180
    local beams = RD.beams
    beams[#beams + 1] = { t = now, yaw = yaw, hub = hb.Position, size = hb.Size }
    if #beams > 8 then table.remove(beams, 1) end
    local recent = 0
    for i = #beams, 1, -1 do if now - beams[i].t <= 0.5 then recent = recent + 1 else break end end
    if recent >= 4 then RD.fanUntil = now + 1.5 end
    for i = #RD.zones, 1, -1 do if RD.zones[i].name == "beam next" then table.remove(RD.zones, i) end end
    if now < RD.fanUntil or #beams < 2 then return end
    local a, b = beams[#beams - 1], beams[#beams]
    local dt = b.t - a.t
    local step = wrap180(b.yaw - a.yaw)
    if dt < 0.3 or dt > 0.8 or math.abs(step) < 15 or math.abs(step) > 25 then return end
    for k = 1, 2 do
        local yaw = math.rad(b.yaw + step * k)
        local at = now + dt * k
        local cf = CFrame.lookAt(b.hub, b.hub + Vector3.new(math.sin(yaw), 0, math.cos(yaw)))
        addZone({ name = "beam next", cframe = cf, size = b.size, from = at, untilAt = at + 2.0, telegraphed = true })
    end
end
-- A body rolling along a line: origin, direction, distance over duration from
-- t0 to t1 (game clock). Half sizes across / along / up. Boxed at the moment
-- asked for by the field.
local function addPath(name, cframe, distance, duration, t0, t1, halfW, halfL, halfH, offset)
    local look = cframe.LookVector
    local flat = Vector3.new(look.X, 0, look.Z)
    if flat.Magnitude < 0.01 then flat = Vector3.new(0, 0, -1) end
    flat = flat.Unit
    local speed = distance / math.max(duration, 0.01)
    addZone({
        name = name, moving = true,
        ox = cframe.Position.X, oy = cframe.Position.Y, oz = cframe.Position.Z,
        dx = flat.X, dz = flat.Z, speed = speed, offset = offset or 0,
        halfW = halfW, halfL = halfL, halfH = math.max(halfH, 6), ground = true,
        from = fromGame(t0), untilAt = fromGame(t1), pathStart = fromGame(t0),
    })
end
local function cubeZone(name, cframe, size, fireGame, holdFor)
    addZone({ name = name, cframe = cframe, size = size, from = fromGame(fireGame), untilAt = fromGame(fireGame) + holdFor, telegraphed = true })
end
local function circleZone(name, position, radius, fireGame, holdFor)
    addZone({ name = name, cframe = CFrame.new(position), size = Vector3.new(radius * 2, 12, radius * 2), round = true,
        from = fromGame(fireGame), untilAt = fromGame(fireGame) + holdFor, telegraphed = true })
end

local SPIKE_RADIUS = { small = 15, medium = 25, large = 40 }
local function args(a, n) return type(a) == "table" and #a >= n end
local HANDLERS = {
    -- The jump's target is where the 67-stud slam lands about 2.5 s later; the
    -- slam Model itself appears only at landing.
    ["First Boss Jump Down"] = function(a) if typeof(a) == "Vector3" then circleZone("slam soon", a, 33.5, gameClock() + 2.5, 1.5) end end,
    ["First Boss Criss Cross Projectile"] = function(a) if args(a, 5) then addPath("criss cross", a[5], a[1], a[2], a[3], a[4], 7.5, 7.5, 8) end end,
    ["First Boss Seeking Spike"] = function(a) if args(a, 5) then addPath("seeking spike", a[5], a[1], a[2], a[3], a[4], 10, 10, 4) end end,
    ["First Boss Big Spike"] = function(a) if args(a, 5) then addPath("big spike", a[5], a[1], a[2], a[3], a[4], 20, 20, 6) end end,
    ["Second Boss Big Hitting Ground Spikes"] = function(a)
        if args(a, 3) and typeof(a[2]) == "CFrame" then circleZone("ground spikes", a[2].Position, SPIKE_RADIUS[a[1]] or 25, a[3], 0.7) end
    end,
    ["Second Boss Moving Beam"] = function(a) if args(a, 5) then addPath("moving beam", a[5], a[1], a[2], a[3], a[4], 29, 4, 6) end end,
    ["Third Boss Bouncing Orb Beam"] = function(a) if typeof(a) == "CFrame" then circleZone("orb beam", a.Position, 12, gameClock(), 6) end end,
    ["Third Boss Sideways Missile"] = function(a) if args(a, 5) then addPath("sideways missile", a[5], a[1], a[2], a[3], a[4], 5, 15, 6, -10) end end,
}
local function lineStrike(cframe, name)
    if typeof(cframe) ~= "CFrame" then return end
    -- The strike mesh grows to 31 long and slides 65 studs behind the cframe.
    cubeZone(name, cframe - cframe.LookVector * 50, Vector3.new(11, 6, 100), gameClock(), 0.6)
end
HANDLERS["Spearman Strike"] = function(a) lineStrike(a, "spearman strike") end
HANDLERS["Warrior Line Strike"] = function(a) lineStrike(a, "warrior strike") end

local function connectRemotes()
    local folder = ReplicatedStorage:FindFirstChild("remotes")
    if not folder then return end
    for _, r in ipairs(folder:GetChildren()) do
        if r:IsA("RemoteEvent") and r.Name:find("BossSpecficEvents", 1, true) then
            RD.connections[#RD.connections + 1] = r.OnClientEvent:Connect(function(name, a)
                local h = HANDLERS[name]
                if h then
                    local ok, err = pcall(h, a)
                    if not ok then heavyDebugThrottled("evt_err", 2, "Reader", tostring(name) .. ": " .. tostring(err)) end
                end
            end)
        end
    end
end

-- The game's own ground telegraphs: exact shape, exact impact time.
local function connectPrecastBridge()
    pcall(function()
        local util = ReplicatedStorage:WaitForChild("Utility", 5)
        local BN = require(util:WaitForChild("BridgeNet2", 5))
        local bridge = BN.ReferenceBridge("precastHitbox")
        local id = BN.ReferenceIdentifier("action")
        RD.connections[#RD.connections + 1] = bridge:Connect(function(p)
            if type(p) ~= "table" then return end
            local eta = (p.delayUntilAttack or 0) - (Workspace:GetServerTimeNow() - (p.startTime or Workspace:GetServerTimeNow()))
            local fire = os.clock() + eta
            if p[id] == "Circle" and p.position then
                addZone({ name = "circle", cframe = CFrame.new(p.position), size = Vector3.new((p.radius or 5) * 2, 12, (p.radius or 5) * 2), round = true, from = fire, untilAt = fire + 0.45, telegraphed = true })
            elseif p.cframe and p.size then
                addZone({ name = "cube", cframe = p.cframe, size = Vector3.new(p.size.X, math.max(p.size.Y, 12), p.size.Z), from = fire, untilAt = fire + 0.45, telegraphed = true })
            end
        end)
    end)
end

-- ------------------------------------------------------------ enemies
local function scanEnemies(now)
    local list = {}
    local me = LocalPlayer.Character
    local function visit(folder)
        for _, m in ipairs(folder:GetChildren()) do
            if m:IsA("Model") and m ~= me then
                local hum = m:FindFirstChildOfClass("Humanoid")
                if hum and hum.Health > 0 and not Players:GetPlayerFromCharacter(m) then
                    local root = m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart
                    if root then
                        local style = m:FindFirstChild("enemyStyle")
                        local melee = m:FindFirstChild("meleeDistance")
                        local prev = RD.enemyPrev and RD.enemyPrev[m]
                        local p = root.Position
                        local vx, vz = 0, 0
                        if prev and now > prev.at then
                            vx, vz = (p.X - prev.x) / (now - prev.at), (p.Z - prev.z) / (now - prev.at)
                        end
                        local extent = math.max(root.Size.X, root.Size.Z) * 0.5
                        list[#list + 1] = {
                            model = m, root = root, humanoid = hum,
                            isBoss = style and type(style.Value) == "string" and lower(style.Value):find("boss", 1, true) ~= nil or false,
                            melee = melee and type(melee.Value) == "number" and melee.Value <= CFG.meleeMobMaxReach or false,
                            meleeDistance = melee and type(melee.Value) == "number" and melee.Value or 4,
                            extent = extent, x = p.X, y = p.Y, z = p.Z, vx = vx, vz = vz,
                        }
                    end
                end
            elseif m:IsA("Folder") or (m:IsA("Model") and m.Name:find("room", 1, true)) then
                visit(m)
            end
        end
    end
    local dungeon = Workspace:FindFirstChild("dungeon")
    if dungeon then visit(dungeon) end
    local enemies = Workspace:FindFirstChild("enemies")
    if enemies then visit(enemies) end
    RD.enemyPrev = RD.enemyPrev or setmetatable({}, { __mode = "k" })
    for _, e in ipairs(list) do RD.enemyPrev[e.model] = { x = e.x, z = e.z, at = now } end
    RD.enemies = list
    -- The Champion's arena kills past about 128 studs from him: every death
    -- out there had nothing near it, and the respawn point is 131-137 out.
    RD.leash = nil
    for _, e in ipairs(list) do
        if e.isBoss and e.model.Name == "Midgardian Champion" then RD.leash = { enemy = e, radius = CFG.leashRadius } break end
    end
end

-- ------------------------------------------------------------ tick
local function readerTick(now)
    -- New instances arrive through DescendantAdded; a cheap sweep every quarter
    -- second catches anything that was renamed or moved in afterwards.
    if now - RD.lastSweep > 0.25 then
        RD.lastSweep = now
        for _, c in ipairs(Workspace:GetChildren()) do
            if c:IsA("Model") or c:IsA("BasePart") then consider(c) end
        end
    end
    -- Model attacks: fade means fired; fade + linger means over.
    for model, r in pairs(RD.models) do
        if not model.Parent or (r.hb and not r.hb.Parent and r.pc and not r.pc.Parent) then
            RD.models[model] = nil
        else
            local pc = r.pc
            if pc and pc.Parent then
                local tr = pc.Transparency
                if tr < r.minT then r.minT = tr end
                if not r.fired and r.minT < 0.9 and tr > r.minT + 0.08 and tr >= 0.9 then
                    r.fired = true
                    if now < r.from then r.from = now end
                    if not r.long then r.untilAt = math.min(r.untilAt, math.max(now + CFG.fadeLinger, r.from + 0.2)) end
                end
            end
            if now > r.untilAt + 0.5 then RD.models[model] = nil end
        end
    end
    -- Bare projectiles: velocity from position; spent when faded and still.
    for part, r in pairs(RD.parts) do
        if not part.Parent then
            RD.parts[part] = nil
        else
            local p = part.Position
            local dt = now - r.at
            if dt > 0.08 then
                r.vx, r.vz = (p.X - r.x) / dt, (p.Z - r.z) / dt
                r.x, r.z, r.at = p.X, p.Z, now
            end
            local speed = math.sqrt(r.vx * r.vx + r.vz * r.vz)
            if part.Transparency >= CFG.spentTransparency and speed < 1 and now - r.spawn > 0.5 then
                RD.parts[part] = nil
            end
        end
    end
    -- Announced zones: gone half a second after they end.
    for i = #RD.zones, 1, -1 do
        if now > RD.zones[i].untilAt + 0.5 then table.remove(RD.zones, i) end
    end
    if now - RD.lastEnemyScan > 0.5 then
        RD.lastEnemyScan = now
        pcall(scanEnemies, now)
    end
end

-- Every hazard as a box the field can test. Static boxes carry cframe/size and
-- a window; moving ones carry an origin, a direction, a speed and half sizes.
local function hazards(now)
    local out = {}
    for _, r in pairs(RD.models) do
        local anchor = (r.hb and r.hb.Parent) and r.hb or ((r.pc and r.pc.Parent) and r.pc or nil)
        if anchor then
            local size = anchor.Size
            if anchor == r.pc and r.hb == nil then size = Vector3.new(size.X, math.max(size.Y, 10), size.Z) end
            local isCyl = anchor:IsA("Part") and anchor.Shape == Enum.PartType.Cylinder
            out[#out + 1] = { cframe = anchor.CFrame, size = size, round = isCyl and anchor.Size.Y == anchor.Size.Z, cyl = isCyl,
                from = r.from, untilAt = r.long and huge or r.untilAt, name = r.name, kind = "model" }
        end
    end
    for part, r in pairs(RD.parts) do
        local speed = math.sqrt(r.vx * r.vx + r.vz * r.vz)
        local size = part.Size
        local half = math.max(size.X, size.Z) * 0.5
        if speed > 2 then
            out[#out + 1] = { moving = true, ox = part.Position.X, oy = part.Position.Y, oz = part.Position.Z,
                dx = r.vx / speed, dz = r.vz / speed, speed = speed, offset = 0, halfW = half, halfL = half, halfH = math.max(size.Y * 0.5, 6),
                from = now, untilAt = now + CFG.projectileLookahead, pathStart = now, name = part.Name, kind = "part" }
        else
            out[#out + 1] = { cframe = part.CFrame, size = Vector3.new(size.X, math.max(size.Y, 8), size.Z), from = now, untilAt = huge, name = part.Name, kind = "part" }
        end
    end
    for _, z in ipairs(RD.zones) do out[#out + 1] = z end
    return out
end

local function start()
    pcall(function()
        local ts = ReplicatedStorage:FindFirstChild("timeSync")
        if ts then RD.timeSync = require(ts) end
    end)
    RD.connections[#RD.connections + 1] = Workspace.DescendantAdded:Connect(function(d)
        task.defer(function() if d.Parent then pcall(consider, d) end end)
    end)
    connectRemotes()
    connectPrecastBridge()
    heavyDebug("Reader", "listening")
end

local function stop()
    for _, c in ipairs(RD.connections) do pcall(function() c:Disconnect() end) end
    RD.connections = {}
end

S.RD = RD
S.readerTick = readerTick
S.hazards = hazards
S.readerStart = start
S.readerStop = stop
S.gameClock = gameClock
end
    end)()
    module(S)
end

-- ===================================== src/field.lua =====================================
do
    local module = (function()
-- field.lua - Where is safe, when, and which nearby spot to be on.
-- Module contract: receives the shared table S; imports from core and reader.
--
-- dangerAt(x, y, z, t): 1 inside a hazard live at time t, fading over a
-- shoulder outside it, 0 clear. A telegraphed box counts as live `dodgeLead`
-- before it fires; a moving box counts as live `dodgePathLead` before it
-- arrives. Melee mobs are hazards too.
--
-- decide(): scores a ring of spots around the character. Each spot's line is
-- sampled at the moments it would be crossed. Danger already on you is
-- discounted only until the ground under you fires (grace); after that,
-- time inside is the hit. Nothing safe within reach: one wider look.
return function(S)
local CFG = S.CFG
local RT = S.RT
local RD = S.RD
local hazards = S.hazards
local Workspace = S.Workspace
local raycastParams = S.raycastParams
local floorY = S.floorY
local heavyDebugThrottled = S.heavyDebugThrottled

local DG = {
    target = nil,           -- Vector3 to go to, or nil (here is fine)
    reason = "",
    dangerHere = 0,
    grace = math.huge,
    lastDecision = -math.huge,
    offsets = {},
    cands = {},
    heading = nil, headingAt = -math.huge,
    boxes = {},
    reach = 2.0,
    halfHeight = 5,
    approach = nil,         -- { x, z, standoff } from the brain
    approachIsBoss = false,
}

local sqrt, abs, max, min, cos, sin, pi = math.sqrt, math.abs, math.max, math.min, math.cos, math.sin, math.pi

local function buildOffsets()
    table.clear(DG.offsets)
    local rings, rays = max(CFG.dodgeRings, 1), max(CFG.dodgeRays, 6)
    for ring = 1, rings do
        local r = CFG.dodgeReach * ring / rings
        local phase = (ring % 2 == 0) and pi / rays or 0
        for i = 0, rays - 1 do
            local a = phase + i / rays * 2 * pi
            DG.offsets[#DG.offsets + 1] = { x = cos(a) * r, z = sin(a) * r, dist = r }
        end
    end
end

-- Depth of a point inside an oriented box (negative outside, distance to the
-- surface in the flat plane), and whether it is at the right height.
local function boxDepth(cf, size, px, py, pz, halfHeight)
    local lp = cf:PointToObjectSpace(Vector3.new(px, py, pz))
    if abs(lp.Y) > size.Y * 0.5 + halfHeight then return -math.huge end
    local ox, oz = abs(lp.X) - size.X * 0.5, abs(lp.Z) - size.Z * 0.5
    if ox <= 0 and oz <= 0 then return -max(ox, oz) end   -- inside: positive depth
    return -sqrt(max(ox, 0) ^ 2 + max(oz, 0) ^ 2)         -- outside: negative distance
end
-- A cylinder Part lies along its X axis; its round face spans Y/Z.
local function cylDepth(cf, size, px, py, pz, halfHeight)
    local lp = cf:PointToObjectSpace(Vector3.new(px, py, pz))
    local r = size.Y * 0.5
    if abs(lp.X) > size.X * 0.5 + halfHeight then return -math.huge end
    return r - sqrt(lp.Y * lp.Y + lp.Z * lp.Z)
end

local function dangerFromDepth(depth, reach, shoulder)
    -- depth > 0 inside; the character's own radius counts.
    local d = depth + reach
    if d >= 0 then return 1 end
    if -d < shoulder then return 1 + d / shoulder end
    return 0
end

local function dangerAt(px, py, pz, t)
    local reach, halfHeight, shoulder = DG.reach, DG.halfHeight, CFG.dodgeShoulder
    local now = DG.now
    local at = now + t
    local worst = 0
    for i = 1, #DG.boxes do
        local b = DG.boxes[i]
        -- A moving body is real from the moment it is announced: the aimed
        -- criss cross sits on the player until its start time and hurts there,
        -- and the big spike's front is already on its way. Static zones fire at
        -- `from`, so they matter from `lead` seconds before.
        local live
        if b.moving then
            live = at <= b.untilAt
        else
            local lead = b.telegraphed and CFG.dodgeLead or (b.from > now and CFG.dodgeLead or 0)
            live = at >= b.from - lead and at <= b.untilAt
        end
        if live then
            local depth
            if b.moving then
                -- Where the body is at time `at`, along its line.
                local along = b.offset + b.speed * max(at - b.pathStart, 0)
                local cx, cz = b.ox + b.dx * along, b.oz + b.dz * along
                -- Remote-announced paths carry the boss's height; they are ground attacks.
                if b.ground or abs(py - b.oy) <= b.halfH + halfHeight then
                    local qx, qz = px - cx, pz - cz
                    local a = abs(qx * b.dx + qz * b.dz) - b.halfL
                    local s = abs(-qx * b.dz + qz * b.dx) - b.halfW
                    depth = (a <= 0 and s <= 0) and -max(a, s) or -sqrt(max(a, 0) ^ 2 + max(s, 0) ^ 2)
                else
                    depth = -math.huge
                end
            elseif b.cyl then
                depth = cylDepth(b.cframe, b.size, px, py, pz, halfHeight)
            elseif b.round then
                local c = b.cframe.Position
                if abs(py - c.Y) <= b.size.Y * 0.5 + halfHeight then
                    depth = b.size.X * 0.5 - sqrt((px - c.X) ^ 2 + (pz - c.Z) ^ 2)
                else
                    depth = -math.huge
                end
            else
                depth = boxDepth(b.cframe, b.size, px, py, pz, halfHeight)
            end
            local d = dangerFromDepth(depth, reach, shoulder)
            if d > worst then worst = d if worst >= 1 then return 1 end end
        end
    end
    -- Outside the arena leash is the attack that has no box.
    local L = RD.leash
    if L and L.enemy.root.Parent then
        local ep = L.enemy.root.Position
        local dx, dz = px - ep.X, pz - ep.Z
        local depth = sqrt(dx * dx + dz * dz) - L.radius
        -- A band, not a half-plane: the walk in from room 2 starts 200 studs
        -- out and is safe; the kill applies once the fight is joined.
        if depth <= 40 then
            local v = dangerFromDepth(depth, reach, shoulder * 2)
            if v > worst then worst = v if worst >= 1 then return 1 end end
        end
    end
    -- Melee mobs: a soft zone, never a wall. Their strikes are telegraphed
    -- Models and count in full above; the zone only keeps the spots away from
    -- them. A hard 19-stud circle made every spot in room 1 look lethal and
    -- the character stood still in the mage shots.
    for i = 1, #RD.enemies do
        local e = RD.enemies[i]
        if e.melee and not e.isBoss then
            local tt = min(t, 0.6)
            local dx, dz = px - (e.x + e.vx * tt), pz - (e.z + e.vz * tt)
            local d = sqrt(dx * dx + dz * dz) - (e.extent + e.meleeDistance + CFG.meleeBuffer)
            local v = dangerFromDepth(-d, reach, shoulder * 2) * 0.5
            if v > worst then worst = v end
        end
    end
    return worst
end

-- Seconds until the ground under the character fires: the soonest live-from
-- among boxes covering it, zero if one is already live, huge if none.
local function graceHere(px, py, pz)
    local now = DG.now
    local grace = math.huge
    for i = 1, #DG.boxes do
        local b = DG.boxes[i]
        if not b.moving and now <= b.untilAt then
            local depth
            if b.cyl then depth = cylDepth(b.cframe, b.size, px, py, pz, DG.halfHeight)
            elseif b.round then
                local c = b.cframe.Position
                depth = (abs(py - c.Y) <= b.size.Y * 0.5 + DG.halfHeight) and (b.size.X * 0.5 - sqrt((px - c.X) ^ 2 + (pz - c.Z) ^ 2)) or -math.huge
            else depth = boxDepth(b.cframe, b.size, px, py, pz, DG.halfHeight) end
            if depth + DG.reach >= 0 then
                local eta = max(b.from - now, 0)
                if eta < grace then grace = eta end
            end
        end
    end
    return grace
end

local function walkable(fromPos, x, y, z, params)
    -- A sweep of a slab the character's size from here to there: anything solid
    -- in the way and the spot is behind a wall.
    local to = Vector3.new(x, y + 2.5, z)
    local from = Vector3.new(fromPos.X, fromPos.Y, fromPos.Z)
    local hit = Workspace:Blockcast(CFrame.new(from), Vector3.new(2.5, 4.5, 2.5), to - from, params)
    return hit == nil
end

local function decide(root, hum)
    local now = os.clock()
    DG.now = now
    DG.boxes = hazards(now)
    DG.reach = root.Size.X * 0.5 + CFG.dodgeMargin
    DG.halfHeight = (hum.HipHeight + root.Size.Y) * 0.5 + 2.5
    if #DG.offsets == 0 or DG.offsetsKey ~= CFG.dodgeReach .. "/" .. CFG.dodgeRings .. "/" .. CFG.dodgeRays then
        buildOffsets()
        DG.offsetsKey = CFG.dodgeReach .. "/" .. CFG.dodgeRings .. "/" .. CFG.dodgeRays
    end
    local rp = root.Position
    local rx, ry, rz = rp.X, rp.Y, rp.Z
    local dwell = CFG.dodgeDwell
    local here0 = dangerAt(rx, ry, rz, 0)
    DG.here0 = here0
    DG.dangerHere = max(here0, dangerAt(rx, ry, rz, dwell * 0.5), dangerAt(rx, ry, rz, dwell))
    -- The burst is for anything arriving within the dwell, not only what is
    -- already here: the big spike front is announced ~2 s out and needs 23
    -- studs of sidestep, which 16 studs/s does not give.
    RT.moveBoost = DG.dangerHere >= CFG.dodgeMoveAt
    local speed = RT.moveBoost and CFG.tweenEscape or (RT.walkSpeed or CFG.tweenWalk)
    local grace = here0 > 0 and graceHere(rx, ry, rz) or math.huge
    DG.grace = grace
    local moveAt = CFG.dodgeMoveAt

    -- Preferences: keep the heading we last took (no left-right shuffle), move
    -- across the target's line rather than along it (strafe), and stay in the
    -- standoff band around the target.
    local hx, hz = 0, 0
    if DG.heading and now - DG.headingAt < 1.0 then hx, hz = DG.heading.X, DG.heading.Z end
    local ap = DG.approach
    local ax, az, adist = 0, 0, 0
    if ap then
        ax, az = ap.x - rx, ap.z - rz
        adist = sqrt(ax * ax + az * az)
        if adist > 0.01 then ax, az = ax / adist, az / adist end
    end

    local function score(ox, oz, dist)
        local T = dist / speed
        local worst, total, n = 0, 0, 0
        local steps = max(2, min(8, math.ceil(dist / 2.5)))
        for k = 1, steps - 1 do
            local f = k / steps
            local d = dangerAt(rx + ox * f, ry, rz + oz * f, T * f)
            local fresh = (T * f < grace) and (d - here0) or d
            if fresh < 0 then fresh = 0 end
            local stale = d < here0 and d or here0
            total = total + fresh + stale * CFG.dodgeInsideWeight
            if fresh > worst then worst = fresh end
            n = n + 1
        end
        local cx, cz = rx + ox, rz + oz
        for _, extra in ipairs({ 0, dwell * 0.5, dwell }) do
            local d = dangerAt(cx, ry, cz, T + extra)
            total = total + d
            if d > worst then worst = d end
            n = n + 1
        end
        return worst, worst * 0.5 + (total / n) * 0.5
    end

    local function costOf(ox, oz, dist, graded)
        local cost = graded + dist * CFG.dodgeDistanceCost
        if (hx ~= 0 or hz ~= 0) and here0 < 1 then
            local dot = (ox * hx + oz * hz) / dist
            cost = cost + 0.05 * (1 - dot) * 0.5
        end
        -- Standing in danger with a target: prefer backing away from it. A
        -- spot behind you is the one that is not in the next attack.
        if ap and here0 >= CFG.dodgeMoveAt and adist > 1 then
            local toward = (ox * ax + oz * az) / dist
            cost = cost + CFG.dodgeOutwardWeight * (toward + 1) * 0.5
        end
        -- The pull toward the target's band applies at every distance: in a
        -- field of attacks the spot outranks travel, so the spots themselves
        -- must carry the approach (5.1.0 reached the Champion this way; a pull
        -- limited to the last thirty studs left it hopping at the entrance).
        -- Weaker far out, so a safe spot still beats a closer risky one.
        if ap then
            local cx, cz = rx + ox, rz + oz
            local dxa, dza = cx - ap.x, cz - ap.z
            local dd = sqrt(dxa * dxa + dza * dza)
            local band = ap.standoff
            local outBy = max(dd - (band + 3), (band - 3) - dd, 0)
            local near = adist < band + 30
            cost = cost + CFG.dodgeApproachWeight * (near and 1 or 0.6) * outBy
            -- Inside the last stretch, moving across the line to the target is
            -- preferred to moving along it.
            if near and CFG.strafe and adist > 1 then
                local radial = abs((ox * ax + oz * az) / dist)
                cost = cost + CFG.dodgeStrafeWeight * radial
            end
        end
        return cost
    end

    -- The target's own body is not a wall: a 60-stud boss beside you made
    -- every far spot behind him unreachable and left only the near hot ones.
    local params = raycastParams(ap and ap.model or nil)
    local cands = DG.cands
    table.clear(cands)
    local function evaluate(scale)
        for _, off in ipairs(DG.offsets) do
            local ox, oz, dist = off.x * scale, off.z * scale, off.dist * scale
            local worst, graded = score(ox, oz, dist)
            cands[#cands + 1] = { ox = ox, oz = oz, dist = dist, danger = worst, cost = costOf(ox, oz, dist, graded) }
        end
        table.sort(cands, function(a, b) return a.cost < b.cost end)
        local best, checked = nil, 0
        for _, c in ipairs(cands) do
            if best and c.cost >= best.cost then break end
            checked = checked + 1
            local x, z = rx + c.ox, rz + c.oz
            local y = floorY(x, ry, z, params)
            -- A far spot may sit up a ramp: the allowed rise grows with distance.
            if y and y - (ry - DG.halfHeight) <= CFG.maxStepHeight + 3 + c.dist * 0.2 and y >= ry - CFG.maxDropHeight then
                if walkable(rp, x, y, z, params) then
                    c.x, c.y, c.z, c.valid = x, y, z, true
                    if not best or c.cost < best.cost then best = c end
                end
            end
            if checked >= 14 and best and best.danger < moveAt then break end
            if checked >= 40 then break end
        end
        return best
    end

    local best = evaluate(1)
    for _, scale in ipairs({ CFG.dodgeFarScale, CFG.dodgeFarScale2 }) do
        if best and best.danger < moveAt then break end
        if scale and scale > 1 then
            table.clear(cands)
            local far = evaluate(scale)
            if far and (not best or far.danger < best.danger) then best = far end
        end
    end

    -- Keep the current spot while its line stays clean and nothing beats it
    -- clearly; drop it the moment its line closes.
    local target = DG.target
    if target then
        local tx, tz = target.X - rx, target.Z - rz
        local d = sqrt(tx * tx + tz * tz)
        if d < 1.2 then
            target = nil
            DG.target = nil
        else
            local worst, graded = score(tx, tz, d)
            if worst >= moveAt then
                target = nil
                DG.target = nil
                DG.reason = "line closed"
            elseif here0 >= moveAt then
                -- Escaping: the spot is kept until reached or its line closes.
                -- Re-picking between two near-equal spots each tick was the
                -- shuttle between two attacks.
                return
            elseif best then
                local stillCost = costOf(tx, tz, d, graded)
                if best.cost > stillCost - CFG.dodgeHysteresis then return end
            end
        end
    end

    if DG.dangerHere < moveAt then
        -- Here is safe. Move only for a reason: out of the band, or a clearly
        -- better spot toward the target.
        if not best or best.danger >= moveAt then
            DG.target = nil
            DG.reason = "waiting for a gap"
            return
        end
        local hereCost = costOf(0, 0, 0.001, 0)
        if best.cost > hereCost - CFG.dodgeHysteresis then
            DG.target = nil
            DG.reason = "safe here"
            return
        end
    end

    if best then
        DG.target = Vector3.new(best.x, best.y, best.z)
        local v = Vector3.new(best.ox, 0, best.oz)
        if v.Magnitude > 0.5 then DG.heading, DG.headingAt = v.Unit, now end
        DG.reason = string.format("danger %.2f, %.0f studs", best.danger, best.dist)
    elseif not DG.target then
        -- Nothing with a floor: away from the nearest enemy, blindly.
        local nearest, nd = nil, math.huge
        for _, e in ipairs(RD.enemies) do
            local dx, dz = rx - e.x, rz - e.z
            local d2 = dx * dx + dz * dz
            if d2 < nd then nearest, nd = e, d2 end
        end
        local away = nearest and Vector3.new(rx - nearest.x, 0, rz - nearest.z).Unit or Vector3.new(0, 0, 1)
        DG.target = rp + away * CFG.dodgeReach
        DG.reason = "blind"
        heavyDebugThrottled("blind", 1, "Field", "no candidate with a floor")
    end
end

S.DG = DG
S.dangerAt = dangerAt
S.decide = decide
end
    end)()
    module(S)
end

-- ===================================== src/mover.lua =====================================
do
    local module = (function()
-- mover.lua - The character goes where it is told, on its own legs.
-- Module contract: receives the shared table S; imports from core.
--
-- Every move is a Humanoid walk (hum:Move), so the server sees a body that
-- walks: legal speed, real collisions, real falls. The 4.12 tween and the
-- 5.1.0 per-frame CFrame write both ended in anti-cheat kicks (an instant hop,
-- a lag-spike jump, a ledge snapped down in one frame). Leaving danger raises
-- WalkSpeed to CFG.tweenEscape for the burst - the client checker only resets
-- values above 45, and 4.12.14 ran the boss approach at 22 for whole runs -
-- and puts it back the moment the burst ends.
return function(S)
local CFG = S.CFG
local RT = S.RT
local LocalPlayer = S.LocalPlayer

local MV = { driving = false, controlsOff = false, lastTarget = nil, facedAt = -math.huge, stallSince = nil, lastPos = nil,
    counts = { arrive = 0, walked = 0, jump = 0, boost = 0 } }
local function count(k) MV.counts[k] = (MV.counts[k] or 0) + 1 end

local function setControls(enabled)
    if MV.controlsOff == (not enabled) then return end
    local ok = pcall(function()
        local scripts = LocalPlayer:FindFirstChild("PlayerScripts")
        local module = scripts and scripts:FindFirstChild("PlayerModule")
        if not module then return end
        local controls = require(module):GetControls()
        if enabled then controls:Enable() else controls:Disable() end
    end)
    if ok then MV.controlsOff = not enabled end
end

-- The burst: WalkSpeed raised while leaving danger, restored after. The value
-- it had is remembered once per burst, so the game's own changes survive.
local function setBoost(hum, on)
    if on then
        if not RT.walkSpeedBefore then
            RT.walkSpeedBefore = hum.WalkSpeed
            count("boost")
        end
        if hum.WalkSpeed ~= CFG.tweenEscape then hum.WalkSpeed = CFG.tweenEscape end
    elseif RT.walkSpeedBefore then
        pcall(function() hum.WalkSpeed = RT.walkSpeedBefore end)
        RT.walkSpeedBefore = nil
    end
end

-- Walk toward `target`. A `speed` above the Humanoid's own WalkSpeed is a
-- burst; one below it walks proportionally slower. Returns true within `arrive`.
local function driveTo(hum, root, target, speed, arrive)
    if not hum or not root then return false end
    arrive = arrive or 1.0
    local pos = root.Position
    local flat = Vector3.new(target.X - pos.X, 0, target.Z - pos.Z)
    local distance = flat.Magnitude
    MV.driving = true
    MV.lastTarget = target
    setControls(false)
    local walk = RT.walkSpeedBefore or hum.WalkSpeed
    if not RT.walkSpeedBefore then RT.walkSpeed = walk end
    setBoost(hum, speed > walk + 0.5)
    if distance <= arrive then
        count("arrive")
        hum:Move(Vector3.zero, false)
        MV.stallSince = nil
        return true
    end
    count("walked")
    -- Face where we go unless the brain aimed us this frame.
    local aimed = os.clock() - MV.facedAt < 0.25
    if hum.AutoRotate == aimed then hum.AutoRotate = not aimed end
    local scale = math.clamp(speed / math.max(hum.WalkSpeed, 1), 0.15, 1)
    hum:Move(flat.Unit * scale, false)
    -- Standing against something for half a second: a hop.
    local now = os.clock()
    if MV.lastPos and (pos - MV.lastPos).Magnitude < 0.05 then
        MV.stallSince = MV.stallSince or now
        if now - MV.stallSince > 0.5 then
            count("jump")
            hum.Jump = true
            MV.stallSince = now
        end
    else
        MV.stallSince = nil
    end
    MV.lastPos = pos
    return false
end

local function face(root, hum, point)
    if not root then return end
    local p = root.Position
    local look = Vector3.new(point.X - p.X, 0, point.Z - p.Z)
    if look.Magnitude < 0.5 then return end
    MV.facedAt = os.clock()
    if hum and hum.AutoRotate then hum.AutoRotate = false end
    root.CFrame = CFrame.lookAt(p, p + look.Unit)
end

local function release(hum, root)
    if MV.driving then
        MV.driving = false
        if hum then hum:Move(Vector3.zero, false) end
    end
    if hum then
        setBoost(hum, false)
        if not hum.AutoRotate then hum.AutoRotate = true end
    end
    MV.stallSince, MV.lastPos = nil, nil
    setControls(true)
end

local function restoreWalkSpeed(hum)
    if hum then setBoost(hum, false) end
end

S.MV = MV
S.driveTo = driveTo
S.faceToward = face
S.releaseMover = release
S.restoreWalkSpeed = restoreWalkSpeed
S.setMoveControls = setControls
end
    end)()
    module(S)
end

-- ===================================== src/brain.lua =====================================
do
    local module = (function()
-- brain.lua - What to do this frame: dodge, fight, or travel.
-- Module contract: receives the shared table S; imports from core, reader,
-- field and mover.
--
-- Priority is fixed: the field's spot outranks everything; then fight the
-- target from its standoff, strafing round it; then travel to the next room.
return function(S)
local CFG = S.CFG
local RT = S.RT
local RD = S.RD
local DG = S.DG
local decide = S.decide
local dangerAt = S.dangerAt
local driveTo = S.driveTo
local faceToward = S.faceToward
local releaseMover = S.releaseMover
-- The speed a walk is planned at: the Humanoid's own, once the mover has read it.
local function walkSpeed() return RT.walkSpeed or CFG.tweenWalk end
local Workspace = S.Workspace
local LocalPlayer = S.LocalPlayer
local PathfindingService = S.PathfindingService
local VirtualInputManager = S.VirtualInputManager
local raycastParams = S.raycastParams
local floorY = S.floorY
local setMovementState = S.setMovementState
local heavyDebug = S.heavyDebug
local heavyDebugThrottled = S.heavyDebugThrottled

local BR = {
    target = nil,
    waypoints = nil, index = 1, pathAt = -math.huge, pathTo = nil,
    strafeDir = 1, strafeFlipAt = -math.huge,
    visitedRooms = {},
    roomBoxes = {},
    lastDecision = -math.huge,
}

local sqrt, abs, max, min = math.sqrt, math.abs, math.max, math.min

local function flat(a, b) local dx, dz = a.X - b.X, a.Z - b.Z return sqrt(dx * dx + dz * dz) end

local function standoffFor(e)
    if e.isBoss then return CFG.bossStandoff end
    if e.melee then return e.extent + CFG.meleeStandoff end
    return e.extent + CFG.rangedStandoff
end

-- The room first: a boss three rooms away sits behind gates that open only
-- when this room is cleared, and pathing at it walked into a wall for good.
local function pickTarget(rp)
    local best, bestScore = nil, math.huge
    local boss, bossD = nil, math.huge
    for _, e in ipairs(RD.enemies) do
        if e.humanoid.Health > 0 and e.model.Parent then
            local d = flat(rp, e.root.Position)
            if e.isBoss then
                if d < bossD then boss, bossD = e, d end
            elseif d < 150 and d < bestScore then
                best, bestScore = e, d
            end
        end
    end
    if best then return best end
    if boss and bossD < 400 then return boss end
    return nil
end

-- ------------------------------------------------------------ travel
local function roomTargets()
    local out = {}
    local dungeon = Workspace:FindFirstChild("dungeon")
    if not dungeon then return out end
    for _, room in ipairs(dungeon:GetChildren()) do
        local order = room:FindFirstChild("order")
        local ord = order and type(order.Value) == "number" and order.Value or (room.Name == "bossRoom" and 99 or nil)
        if ord then
            local anchor
            local ef = room:FindFirstChild("enemyFolder")
            if ef then
                for _, s in ipairs(ef:GetChildren()) do
                    if s:IsA("BasePart") then anchor = s.Position break end
                    if s:IsA("Model") and s.PrimaryPart then anchor = s.PrimaryPart.Position break end
                end
            end
            if not anchor then
                local p = room:FindFirstChildWhichIsA("BasePart", true)
                anchor = p and p.Position
            end
            if anchor then
                -- The room's footprint, measured once: standing inside it is what
                -- 'reached' means. Anchors can sit far from the path walked.
                local box = BR.roomBoxes[room]
                if box == nil then
                    local ok, cf, size = pcall(function() return room:GetBoundingBox() end)
                    box = ok and { cf = cf, size = size } or false
                    BR.roomBoxes[room] = box
                end
                out[#out + 1] = { order = ord, position = anchor, name = room.Name, box = box or nil }
            end
        end
    end
    table.sort(out, function(a, b) return a.order < b.order end)
    return out
end

-- The next room is the first one past the furthest we have stood in. A room
-- whose anchor we never came within 25 studs of (its mobs died from range) is
-- behind us all the same; 5.1.9 walked back to room 2 after the Champion.
local function nextRoom(rp)
    local rooms = roomTargets()
    for _, r in ipairs(rooms) do
        local inside = false
        if r.box then
            local lp = r.box.cf:PointToObjectSpace(rp)
            inside = abs(lp.X) <= r.box.size.X * 0.5 + 4 and abs(lp.Z) <= r.box.size.Z * 0.5 + 4
        end
        if (inside or flat(rp, r.position) < 25) and r.order > (BR.reachedOrder or 0) then BR.reachedOrder = r.order end
    end
    for _, r in ipairs(rooms) do
        if r.order > (BR.reachedOrder or 0) then return r end
    end
    return nil
end

local function computePath(from, to)
    local path = PathfindingService:CreatePath({ AgentRadius = 2.5, AgentHeight = 5, AgentCanJump = true, WaypointSpacing = 4 })
    local ok = pcall(function() path:ComputeAsync(from, to) end)
    if ok and path.Status == Enum.PathStatus.Success then
        local wps = {}
        for _, w in ipairs(path:GetWaypoints()) do wps[#wps + 1] = w.Position end
        if #wps >= 2 then return wps end
    end
    -- Straight line, in steps, when the navmesh has no answer.
    local wps = {}
    local d = flat(from, to)
    local n = max(1, min(24, math.floor(d / 8)))
    for i = 1, n do wps[#wps + 1] = from:Lerp(to, i / n) end
    return wps
end

-- Is the straight line to `to` walkable? A slab the character's size swept
-- along it, against everything solid.
local function lineClear(rp, to, exclude)
    local params = raycastParams(exclude)
    local from = rp
    local dest = Vector3.new(to.X, rp.Y, to.Z)
    local hit = Workspace:Blockcast(CFrame.new(from), Vector3.new(2.5, 4.5, 2.5), dest - from, params)
    return hit == nil
end

-- Walk toward `to`. A moving target must not mean a new plan every frame: the
-- Champion walks, and replanning from scratch each half second reset the
-- index to the waypoint under the character, which shuffled on the spot for
-- a whole fight. Straight when the line is clear; otherwise a path, replanned
-- rarely, resumed past the waypoints already behind.
local function travel(hum, root, to, speed, label, exclude)
    local rp = root.Position
    local now = os.clock()
    if flat(rp, to) < 70 and lineClear(rp, to, exclude) then
        BR.waypoints = nil
        driveTo(hum, root, to, speed, 1.5)
        setMovementState(label .. " straight")
        return
    end
    if not BR.waypoints or not BR.pathTo or flat(BR.pathTo, to) > 20 or now - BR.pathAt > 4 or BR.index > #BR.waypoints then
        BR.waypoints = computePath(rp, to)
        BR.pathAt = now
        BR.pathTo = to
        -- Resume past whatever is already behind us.
        BR.index = 1
        for i, w in ipairs(BR.waypoints) do
            local dx, dz = w.X - rp.X, w.Z - rp.Z
            local nx, nz = to.X - rp.X, to.Z - rp.Z
            if dx * nx + dz * nz > 0 and flat(rp, w) > 2.5 then BR.index = i break end
        end
    end
    local wp = BR.waypoints[BR.index]
    while wp and flat(rp, wp) < 3 and BR.index < #BR.waypoints do
        BR.index = BR.index + 1
        wp = BR.waypoints[BR.index]
    end
    if not wp then return end
    -- No progress for a while: the way is shut (a gate, a wall the navmesh
    -- did not know). Replan, and after that skip the waypoint.
    if not BR.progressAt or flat(rp, BR.progressPos or rp) > 1.5 then BR.progressAt, BR.progressPos = now, rp end
    if now - BR.progressAt > 2.5 then
        BR.progressAt = now
        if BR.index < #BR.waypoints then BR.index = BR.index + 1 else BR.waypoints = nil end
        heavyDebugThrottled("stall", 2, "Brain", "no progress; skipping a waypoint")
        return
    end
    driveTo(hum, root, wp, speed, 1.5)
    setMovementState(string.format("%s %d/%d", label, BR.index, #BR.waypoints))
end

-- ------------------------------------------------------------ fighting
local function pressKey(key)
    pcall(function() VirtualInputManager:SendKeyEvent(true, key, false, game) end)
    task.delay(0.05, function() pcall(function() VirtualInputManager:SendKeyEvent(false, key, false, game) end) end)
end

local function fight(hum, root, e, now)
    local ep = e.root.Position
    local d = flat(root.Position, ep)
    faceToward(root, hum, ep)
    if d <= CFG.abilityRadius then
        if CFG.autoQ and now - RT.lastQ >= CFG.abilityInterval then RT.lastQ = now pressKey(Enum.KeyCode.Q) end
        if CFG.autoE and now - RT.lastE >= CFG.abilityInterval then RT.lastE = now pressKey(Enum.KeyCode.E) end
    end
    if CFG.autoAttack and d <= CFG.attackRange + e.extent and now - RT.lastClick >= CFG.clickInterval then
        RT.lastClick = now
        local tool = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Tool")
        if tool then pcall(function() tool:Activate() end) end
    end
end

-- A point a few studs along the tangent round the target, flipped when the
-- way ahead is dangerous or blocked or every few seconds for variety.
local function strafePoint(root, e, standoff, now)
    local rp = root.Position
    local ep = e.root.Position
    local rx, rz = rp.X - ep.X, rp.Z - ep.Z
    local d = sqrt(rx * rx + rz * rz)
    if d < 0.5 then return nil end
    local ux, uz = rx / d, rz / d
    local tx, tz = -uz * BR.strafeDir, ux * BR.strafeDir
    local stepLen = 6
    -- Pull toward the band as we go round; a melee mob inside the band is
    -- backed away from, not circled.
    local radial = standoff - d
    local clampR = e.melee and 8 or 4
    if e.melee and radial > 2 then stepLen = 2 end
    local px, pz = rp.X + tx * stepLen + ux * max(min(radial, clampR), -clampR), rp.Z + tz * stepLen + uz * max(min(radial, clampR), -clampR)
    local params = raycastParams(e.model)
    local y = floorY(px, rp.Y, pz, params)
    local blocked = (not y) or abs(y - rp.Y) > CFG.maxStepHeight + 3 or dangerAt(px, rp.Y, pz, stepLen / walkSpeed()) >= CFG.dodgeMoveAt
    if blocked or now - BR.strafeFlipAt > 4 then
        BR.strafeDir = -BR.strafeDir
        BR.strafeFlipAt = now
        if blocked then return nil end
    end
    return Vector3.new(px, y or rp.Y, pz)
end

-- Is the next stretch of a walk safe for the moment it is crossed? Three
-- samples along it at the times they would be reached, plus a short dwell.
local function stepSafe(rp, to, speed)
    local dx, dz = to.X - rp.X, to.Z - rp.Z
    local len = sqrt(dx * dx + dz * dz)
    if len < 0.1 then return true end
    local step = min(len, 6)
    local ux, uz = dx / len * step, dz / len * step
    local T = step / max(speed, 4)
    local d = max(dangerAt(rp.X + ux * 0.5, rp.Y, rp.Z + uz * 0.5, T * 0.5), dangerAt(rp.X + ux, rp.Y, rp.Z + uz, T), dangerAt(rp.X + ux, rp.Y, rp.Z + uz, T + 0.3))
    return d < CFG.dodgeMoveAt
end

-- ------------------------------------------------------------ tick
local function brainTick(now)
    local char = LocalPlayer.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not hum or not root or hum.Health <= 0 then
        setMovementState("no character")
        BR.waypoints = nil
        return
    end

    local target = pickTarget(root.Position)
    BR.target = target
    if target then
        DG.approach = { x = target.root.Position.X, z = target.root.Position.Z, standoff = standoffFor(target), model = target.model }
    else
        DG.approach = nil
    end

    if now - DG.lastDecision >= CFG.dodgeInterval then
        DG.lastDecision = now
        local ok, err = pcall(decide, root, hum)
        if not ok then heavyDebugThrottled("decide_err", 2, "Field", tostring(err)) end
    end

    -- 1. The field's spot outranks everything while the ground here is
    -- dangerous now, or when the walk the brain wants is itself unsafe. With
    -- something always about to arrive somewhere, a spot chosen for future
    -- danger must not stop a walk whose own next step is clean.
    if DG.target then
        local useSpot = (DG.here0 or 0) >= CFG.dodgeMoveAt
        if not useSpot then
            local walkTo
            if target then
                local standoff = standoffFor(target)
                if flat(root.Position, target.root.Position) > standoff + 3 then walkTo = target.root.Position end
            end
            if not walkTo then
                local room = nextRoom(root.Position)
                walkTo = room and room.position
            end
            useSpot = walkTo == nil or not stepSafe(root.Position, walkTo, walkSpeed())
        end
        if useSpot then
            local speed = RT.moveBoost and CFG.tweenEscape or walkSpeed()
            driveTo(hum, root, DG.target, speed, 1.2)
            setMovementState("dodge " .. DG.reason)
            if target then fight(hum, root, target, now) end
            return
        end
    end

    -- 2. A target: close to standoff, then fight and strafe.
    if target then
        local standoff = standoffFor(target)
        local d = flat(root.Position, target.root.Position)
        if d > standoff + 3 then
            local speed = (target.isBoss and d > 45) and CFG.tweenEscape or walkSpeed()
            travel(hum, root, target.root.Position, speed, "approach", target.model)
            if d <= CFG.abilityRadius then fight(hum, root, target, now) end
            return
        end
        BR.waypoints = nil
        fight(hum, root, target, now)
        if target.isBoss and d < standoff - 12 then
            -- Well inside the band (the boss leapt onto us, or the fan began): straight out.
            local rp, ep = root.Position, target.root.Position
            local away = Vector3.new(rp.X - ep.X, 0, rp.Z - ep.Z)
            if away.Magnitude > 0.5 then
                driveTo(hum, root, rp + away.Unit * 12, CFG.tweenEscape, 1.0)
                setMovementState("back off")
                return
            end
        end
        if CFG.strafe then
            local p = strafePoint(root, target, standoff, now)
            if p then
                local speed = (target.melee and d < standoff - 2) and CFG.tweenEscape or walkSpeed() * CFG.strafeSpeedFraction
                driveTo(hum, root, p, speed, 1.0)
                setMovementState("strafe")
                return
            end
        end
        releaseMover(hum, root)
        setMovementState("in range")
        return
    end

    -- 3. Nothing to fight: on to the next room.
    local room = nextRoom(root.Position)
    if room then
        travel(hum, root, room.position, walkSpeed(), "to " .. room.name)
        return
    end
    releaseMover(hum, root)
    setMovementState("idle")
end

S.BR = BR
S.brainTick = brainTick
S.standoffFor = standoffFor
end
    end)()
    module(S)
end

-- ===================================== src/draw.lua =====================================
do
    local module = (function()
-- draw.lua - One translucent box per hazard, coloured by stage, and the spot.
-- Module contract: receives the shared table S; imports from core, reader, field.
return function(S)
local CFG = S.CFG
local RT = S.RT
local DG = S.DG
local hazards = S.hazards
local getVisualRoot = S.getVisualRoot

local DR = { folder = nil, parts = {}, target = nil, lastDraw = -math.huge }

local function folder()
    if DR.folder and DR.folder.Parent then return DR.folder end
    local f = Instance.new("Folder")
    f.Name = "Hazards"
    f.Parent = getVisualRoot()
    DR.folder = f
    return f
end

local function newBox()
    local p = Instance.new("Part")
    p.Anchored, p.CanCollide, p.CanQuery, p.CanTouch, p.CastShadow = true, false, false, false, false
    p.Material = Enum.Material.Neon
    p.Transparency = CFG.hazardTransparency
    p.Parent = folder()
    return p
end

local function stageColor(b, now)
    if now >= b.from then return CFG.colorLive end
    if b.moving then return CFG.colorSoon end
    if b.from - now <= CFG.dodgeLead then return CFG.colorSoon end
    return CFG.colorFloor
end

local function drawTick(now)
    if now - DR.lastDraw < 0.1 then return end
    -- Our own drawing must never be the lag: only what is near, and not many.
    local lp = S.LocalPlayer.Character
    local rt = lp and lp:FindFirstChild("HumanoidRootPart")
    local rp = rt and rt.Position
    DR.lastDraw = now
    local used = {}
    if CFG.drawHazards then
        local list = hazards(now)
        local drawn = 0
        for i, b in ipairs(list) do
            local bx, bz
            if b.moving then bx, bz = b.ox, b.oz else bx, bz = b.cframe.Position.X, b.cframe.Position.Z end
            local near = not rp or ((bx - rp.X) ^ 2 + (bz - rp.Z) ^ 2) < 130 * 130
            if near and drawn < 60 then
            drawn = drawn + 1
            local key = i
            local p = DR.parts[key]
            if not p or not p.Parent then p = newBox() DR.parts[key] = p end
            used[key] = true
            if b.moving then
                -- The rectangle it sweeps over the window we look ahead.
                local len = b.speed * CFG.projectileLookahead + b.halfL * 2
                local along = b.offset + b.speed * math.max(now - b.pathStart, 0)
                local cx, cz = b.ox + b.dx * (along + len * 0.5 - b.halfL), b.oz + b.dz * (along + len * 0.5 - b.halfL)
                p.Size = Vector3.new(b.halfW * 2, 1, len)
                local y = (b.ground and rp) and (rp.Y - 2.4) or (b.oy - b.halfH + 0.6)
                p.CFrame = CFrame.lookAt(Vector3.new(cx, y, cz), Vector3.new(cx + b.dx, y, cz + b.dz))
                p.Shape = Enum.PartType.Block
            elseif b.round then
                p.Shape = Enum.PartType.Cylinder
                p.Size = Vector3.new(0.6, b.size.X, b.size.X)
                p.CFrame = b.cframe * CFrame.Angles(0, 0, math.rad(90))
            elseif b.cyl then
                p.Shape = Enum.PartType.Cylinder
                p.Size = Vector3.new(b.size.X, b.size.Y, b.size.Z)
                p.CFrame = b.cframe
            else
                p.Shape = Enum.PartType.Block
                p.Size = Vector3.new(b.size.X, math.min(b.size.Y, 1.5), b.size.Z)
                p.CFrame = b.cframe - Vector3.new(0, b.size.Y * 0.5 - 0.8, 0)
            end
            local c = stageColor(b, now)
            if p.Color ~= c then p.Color = c end
            p.Transparency = CFG.hazardTransparency
            end
        end
    end
    for key, p in pairs(DR.parts) do
        if not used[key] then p:Destroy() DR.parts[key] = nil end
    end
    if CFG.drawTarget and DG.target then
        local t = DR.target
        if not t or not t.Parent then
            t = Instance.new("Part")
            t.Anchored, t.CanCollide, t.CanQuery, t.CanTouch = true, false, false, false
            t.Material = Enum.Material.Neon
            t.Color = CFG.colorTarget
            t.Transparency = 0.35
            t.Size = Vector3.new(2, 5, 2)
            t.Parent = folder()
            DR.target = t
        end
        t.CFrame = CFrame.new(DG.target + Vector3.new(0, 3, 0))
    elseif DR.target then
        DR.target:Destroy()
        DR.target = nil
    end
end

local function clearDrawing()
    if DR.folder then DR.folder:Destroy() end
    DR.folder, DR.target = nil, nil
    table.clear(DR.parts)
end

S.drawTick = drawTick
S.clearDrawing = clearDrawing
end
    end)()
    module(S)
end

-- ===================================== src/lobby.lua =====================================
do
    local module = (function()
-- lobby.lua - The loop outside the fight: queue a run from the lobby, replay it when it ends.
-- Module contract: receives the shared table S. Everything this module needs from
-- earlier modules is pulled into locals below; everything later modules need is
-- assigned onto S at the bottom. Load order is fixed by main.lua / build.py.
return function(S)
local RT = S.RT
local CFG = S.CFG
local Workspace = S.Workspace
local ReplicatedStorage = S.ReplicatedStorage
local LocalPlayer = S.LocalPlayer
local heavyDebug = S.heavyDebug

-- =========================================================================
-- AUTO QUEUE (4.12.5)
--
-- Read from the game's own lobby scripts (PlayerScripts.Ui.queue.* and the
-- Replay button, decompiled live on 2026-09-02; copies under game/lobby/).
-- The buttons are thin: every one of them ends in a remote call, so the loop
-- makes the same calls and never has to find a button on screen.
--
--   Lobby   remotes.createLobby:InvokeServer(map, difficulty, minLevel,
--           hardcore, private, waveDefence) -> true when the party exists,
--           then remotes.startDungeon:FireServer(). Map and difficulty are
--           the names on the lobby's own tiles ("Northern Lands",
--           "Nightmare"). The intro screen and the Play button are cosmetic;
--           the server does not need them pressed.
--   Level   workspace.dungeon.bossRoom.dungeonFinished (BoolValue) turns
--           true when the run is over, win or lose. The party owner
--           (PlaceManager.GetPlaceTeleportData().ownerId) may then send
--           remotes.replayDungeon:FireServer(data) with the same values the
--           game's Replay button collects, and the server rebuilds the run.
--           Anyone else simply waits to be returned to the lobby, where the
--           lobby half of this loop queues again.
--
-- Which place we are in comes from ReplicatedStorage.Utility.PlaceManager
-- ("Lobby" / "Level"), the game's own answer.
-- =========================================================================

local LB = {
    place = nil,
    placeAt = -math.huge,
    arrivedAt = nil,
    lastAttempt = -math.huge,
    attempts = 0,
    busy = false,
    status = "off",
    finishedSeenAt = nil,
    replayFired = false,
    placeManager = nil,
    farmAppliedFor = nil,
    levelArrivedAt = nil,
    lastStartPress = -math.huge,
}

local function placeManager()
    if LB.placeManager ~= nil then return LB.placeManager or nil end
    local ok, pm = pcall(function()
        local util = ReplicatedStorage:FindFirstChild("Utility")
        local mod = util and util:FindFirstChild("PlaceManager")
        return mod and require(mod) or nil
    end)
    LB.placeManager = (ok and pm) or false
    return LB.placeManager or nil
end

-- "Lobby" or "Level" (a dungeon), from the game's own PlaceManager, with
-- the workspace values as a fallback.
local function placeName()
    local pm = placeManager()
    if pm and pm.GetPlaceName then
        local ok, name = pcall(pm.GetPlaceName)
        if ok and type(name) == "string" and name ~= "" then return name end
    end
    local dn = Workspace:FindFirstChild("dungeonName")
    if dn and dn.Value ~= "" then return "Level" end
    if Workspace:FindFirstChild("Lobby") then return "Lobby" end
    return "?"
end

-- The master switch, by place: off in the lobby (nothing to fight, and the
-- loop must not try), on in a dungeon. Applied once per place change, so a
-- hand on the switch inside a place is respected.
local function setFarm(on, why)
    if RT.farmEnabled == on then return end
    RT.farmEnabled = on
    if S.setLoopButtonState then pcall(S.setLoopButtonState) end
    heavyDebug("Queue", (on and "Autofarm on: " or "Autofarm off: ") .. why)
end

local function setStatus(text)
    if LB.status ~= text then
        LB.status = text
        if S.refreshQueuePanel then S.refreshQueuePanel() end
    end
end

local function remote(name)
    local folder = ReplicatedStorage:FindFirstChild("remotes")
    return folder and folder:FindFirstChild(name) or nil
end

-- The lobby half. Returns true if an attempt was started.
local function queueNow(reason)
    if LB.busy then return false end
    LB.busy = true
    LB.lastAttempt = os.clock()
    LB.attempts = LB.attempts + 1
    task.spawn(function()
        local ok, err = pcall(function()
            local create, start = remote("createLobby"), remote("startDungeon")
            if not create or not start then error("the lobby remotes are not present") end
            -- A party we already made (a retry after a start that did not
            -- teleport): just start it.
            local gui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
            local queueGui = gui and gui:FindFirstChild("queueGui")
            local info = queueGui and queueGui:FindFirstChild("lobbyInfo")
            if info and info.Visible then
                setStatus("party open; starting")
                start:FireServer()
                return
            end
            setStatus(string.format("creating %s, %s", tostring(CFG.autoQueueMap), tostring(CFG.autoQueueDifficulty)))
            local accepted = create:InvokeServer(CFG.autoQueueMap, CFG.autoQueueDifficulty,
                tonumber(CFG.autoQueueMinLevel) or 0, CFG.autoQueueHardcore == true,
                CFG.autoQueuePrivate == true, false)
            if accepted ~= true then
                setStatus("declined by the game")
                heavyDebug("Queue", string.format("The game declined the party (%s, %s): %s",
                    tostring(CFG.autoQueueMap), tostring(CFG.autoQueueDifficulty), tostring(accepted)))
                return
            end
            task.wait(CFG.autoQueueStartDelay)
            setStatus("starting")
            start:FireServer()
            heavyDebug("Queue", string.format("Queued %s on %s%s; start sent (%s).",
                tostring(CFG.autoQueueMap), tostring(CFG.autoQueueDifficulty),
                CFG.autoQueueHardcore and ", hardcore" or "", tostring(reason or "auto")))
        end)
        if not ok then
            setStatus("failed; will retry")
            heavyDebug("Queue", "Queueing threw: " .. tostring(err))
        end
        LB.busy = false
    end)
    return true
end

-- The dungeon half: exactly what the game's own Replay button sends.
local function collectDungeonData()
    local data = {}
    for _, name in ipairs({ "dungeonName", "dungeonProgress", "dungeonStarted", "hardcore" }) do
        local v = Workspace:FindFirstChild(name)
        if v and v:IsA("ValueBase") then data[name] = v.Value end
    end
    if data.hardcore ~= nil then data.isHardcore = data.hardcore end
    local dungeon = Workspace:FindFirstChild("dungeon")
    if dungeon then
        for _, child in ipairs(dungeon:GetChildren()) do
            if child:IsA("ValueBase") then data[child.Name] = child.Value end
        end
        local bossRoom = dungeon:FindFirstChild("bossRoom")
        if bossRoom then
            for _, child in ipairs(bossRoom:GetChildren()) do
                if child:IsA("ValueBase") then data[child.Name] = child.Value end
            end
        end
    end
    return data
end

local function isOwner()
    local pm = placeManager()
    if not (pm and pm.GetPlaceTeleportData) then return true end
    local ok, td = pcall(pm.GetPlaceTeleportData)
    if not ok or type(td) ~= "table" or td.ownerId == nil then return true end
    return td.ownerId == LocalPlayer.UserId
end

local function dungeonFinishedValue()
    local dungeon = Workspace:FindFirstChild("dungeon")
    local bossRoom = dungeon and dungeon:FindFirstChild("bossRoom")
    local v = bossRoom and bossRoom:FindFirstChild("dungeonFinished")
    if v and v:IsA("BoolValue") then return v end
    return nil
end

local function replayNow()
    local replay = remote("replayDungeon")
    if not replay then return false end
    local data = collectDungeonData()
    if not data.dungeonName then return false end
    LB.replayFired = true
    replay:FireServer(data)
    setStatus("replay sent")
    heavyDebug("Queue", "Run finished; replay sent for " .. tostring(data.dungeonName) .. ".")
    return true
end

local function lobbyTick(now)
    -- The place does not change mid-session; re-read it now and then in case
    -- the module was not ready at the first tick.
    if not LB.place or LB.place == "?" or now - LB.placeAt > 5 then
        LB.place, LB.placeAt = placeName(), now
    end
    if CFG.autoFarmByPlace and LB.place ~= LB.farmAppliedFor and (LB.place == "Lobby" or LB.place == "Level") then
        LB.farmAppliedFor = LB.place
        setFarm(LB.place == "Level", LB.place == "Level" and "in a dungeon" or "in the lobby")
    end
    if LB.place == "Level" and CFG.autoStartDungeon then
        LB.levelArrivedAt = LB.levelArrivedAt or now
        local startedValue = Workspace:FindFirstChild("dungeonStarted")
        if startedValue and startedValue:IsA("BoolValue") and not startedValue.Value
            and now - LB.levelArrivedAt >= CFG.autoStartDelay and now - LB.lastStartPress >= 10 then
            LB.lastStartPress = now
            local startRemote = remote("changeStartValue")
            if startRemote then
                pcall(function() startRemote:FireServer() end)
                heavyDebug("Queue", "Dungeon not started; START pressed.")
            end
        end
    end
    if not CFG.autoQueue then
        setStatus("off")
        return
    end
    if LB.place == "Lobby" then
        LB.arrivedAt = LB.arrivedAt or now
        if LB.busy then return end
        local waited = now - LB.arrivedAt
        if waited < CFG.autoQueueDelay then
            setStatus(string.format("in the lobby; queueing in %.0fs", CFG.autoQueueDelay - waited))
            return
        end
        if now - LB.lastAttempt < CFG.autoQueueRetry then return end
        queueNow("auto")
    elseif LB.place == "Level" then
        LB.arrivedAt = nil
        if not CFG.autoQueueReplay or LB.replayFired then return end
        local v = dungeonFinishedValue()
        if v and v.Value then
            LB.finishedSeenAt = LB.finishedSeenAt or now
            if not isOwner() then
                setStatus("run finished; waiting for the game to return us")
                return
            end
            local left = CFG.autoQueueReplayDelay - (now - LB.finishedSeenAt)
            if left > 0 then
                setStatus(string.format("run finished; replay in %.0fs", left))
                return
            end
            replayNow()
        else
            setStatus("in a run")
        end
    else
        setStatus("waiting for the place to load")
    end
end

S.LB = LB
S.lobbyTick = lobbyTick
S.queueNow = queueNow
S.replayNow = replayNow
-- The lobby's own tiles, in its order, released ones only (2026-09-02).
S.QUEUE_MAPS = {
    "Desert Temple", "Winter Outpost", "Pirate Island", "King's Castle", "The Underworld",
    "Samurai Palace", "The Canals", "Steampunk Sewers", "Ghastly Harbor", "Orbital Outpost",
    "Volcanic Chambers", "Enchanted Forest", "Aquatic Temple", "Northern Lands", "Egg Island",
}
S.QUEUE_DIFFICULTIES = { "Easy", "Medium", "Hard", "Insane", "Nightmare" }
end
    end)()
    module(S)
end

-- ===================================== src/config.lua =====================================
do
    local module = (function()
-- config.lua - Settings on disk: load at start, save when they change.
-- Module contract: receives the shared table S; imports from core.
return function(S)
local CFG = S.CFG
local RT = S.RT
local LocalPlayer = S.LocalPlayer
local heavyDebug = S.heavyDebug

local FILE = "DungeonAutofarm5_config.json"
local CF = { lastJson = nil, lastAt = -math.huge }

local function hasFiles()
    return type(writefile) == "function" and type(readfile) == "function" and type(isfile) == "function"
end

-- Only settings are saved: toggles, standoffs, speeds, queue choices, colours.
-- Dodge tuning (dwell, leads, reach, timings) follows the code even though
-- the UI shows sliders for it; a saved 0.6 s dwell silently undid 5.1.14.
local PERSIST = {
    "abilityRadius", "attackRange", "autoAttack", "autoE", "autoQ", "autoFarmByPlace",
    "autoQueue", "autoQueueDelay", "autoQueueDifficulty", "autoQueueHardcore", "autoQueueMap", "autoQueuePrivate", "autoQueueReplay", "autoStartDungeon",
    "bossStandoff", "meleeStandoff", "rangedStandoff", "strafe", "strafeSpeedFraction", "tweenEscape", "tweenWalk",
    "colorFloor", "colorLive", "colorSoon", "drawHazards", "drawTarget", "hazardTransparency",
    "debugPrints",
    "menuKey",
}
local PERSIST_SET = {}
for _, k in ipairs(PERSIST) do PERSIST_SET[k] = true end
S.persistKeys = PERSIST_SET

local function snapshot()
    local out = {}
    for _, k in ipairs(PERSIST) do
        local v = CFG[k]
        local t = typeof(v)
        if t == "number" or t == "boolean" or t == "string" then out[k] = v
        elseif t == "Color3" then out[k] = "#" .. v:ToHex() end
    end
    out.__version = S.SCRIPT_VERSION
    out.__farmEnabled = RT.farmEnabled
    return out
end

local function apply(data)
    for k, v in pairs(data) do
        local cur = CFG[k]
        if cur ~= nil and PERSIST_SET[k] then
            local t = typeof(cur)
            if t == "Color3" and type(v) == "string" then
                local ok, c = pcall(Color3.fromHex, v)
                if ok then CFG[k] = c end
            elseif typeof(v) == t then
                CFG[k] = v
            end
        end
    end
end

local function saveConfig()
    if not hasFiles() then return false end
    local ok, json = pcall(function() return game:GetService("HttpService"):JSONEncode(snapshot()) end)
    if not ok then return false end
    local wrote = pcall(writefile, FILE, json)
    if wrote then CF.lastJson = json end
    return wrote
end

local function loadConfig()
    if not hasFiles() then return false end
    local exists = false
    pcall(function() exists = isfile(FILE) end)
    if not exists then return false end
    local ok, data = pcall(function() return game:GetService("HttpService"):JSONDecode(readfile(FILE)) end)
    if not ok or type(data) ~= "table" then return false end
    apply(data)
    heavyDebug("Config", "loaded " .. FILE)
    return true
end

local function autosaveTick(now)
    if now - CF.lastAt < CFG.autosaveInterval then return end
    CF.lastAt = now
    if not hasFiles() then return end
    local ok, json = pcall(function() return game:GetService("HttpService"):JSONEncode(snapshot()) end)
    if ok and json ~= CF.lastJson then
        if pcall(writefile, FILE, json) then CF.lastJson = json end
    end
end

local function startAutosave()
    if RT.autosaveStarted then return end
    RT.autosaveStarted = true
    pcall(function()
        LocalPlayer.OnTeleport:Connect(function(state)
            if state == Enum.TeleportState.Started or state == Enum.TeleportState.RequestedFromServer then saveConfig() end
        end)
    end)
end

S.loadConfig = loadConfig
S.saveConfig = saveConfig
S.autosaveTick = autosaveTick
S.startAutosave = startAutosave
end
    end)()
    module(S)
end

