    end
    local hudTitle = line("dqr autofarm  " .. SCRIPT_VERSION, 1)
    local hudStatus = line("", 2)
    local hudTarget = line("", 3)
    local hudWorld = line("[" .. CFG.menuKey .. "] opens the interface", 4)
    local frames, elapsed, fps = 0, 0, 0
    RT.hudConnection = RunService.Heartbeat:Connect(function(dt)
        if RT.destroyed then return end
        frames, elapsed = frames + 1, elapsed + dt
        if elapsed >= 0.5 then fps = frames / elapsed frames, elapsed = 0, 0 end
        hudStatus.Text = string.format("%s  |  %s", RT.farmEnabled and "running" or "off", tostring(RT.movementState))
        hudStatus.TextColor3 = RT.farmEnabled and (T.StatusGood or Color3.fromRGB(90, 220, 120)) or (T.StatusBad or Color3.fromRGB(230, 90, 90))
        local t = BR.target
        hudTarget.Text = t and string.format("target: %s  %.0f%%", t.model.Name, t.humanoid.Health / math.max(t.humanoid.MaxHealth, 1) * 100) or "target: none"
        hudWorld.Text = string.format("%d enemies  %d hazards  fps %d  %.1fms", #RD.enemies, RD.count, math.floor(fps + 0.5), RT.tickMs or 0)
    end)
end

S.buildUI = buildUI
S.destructScript = destructScript
S.setLoopButtonState = function() if UI.masterRender then pcall(UI.masterRender) end end
S.refreshAllWidgets = refreshAll
end
    end)()
    module(S)
end

-- ===================================== src/main.lua =====================================
do
    local module = (function()
-- main.lua - Startup and the heartbeat.
-- Module contract: receives the shared table S; imports from everything before it.
return function(S)
local CFG = S.CFG
local RT = S.RT
local RD = S.RD
local SCRIPT_VERSION = S.SCRIPT_VERSION
local SCRIPT_BUILD_DATE = S.SCRIPT_BUILD_DATE
local LocalPlayer = S.LocalPlayer
local RunService = S.RunService
local readerStart = S.readerStart
local readerTick = S.readerTick
local brainTick = S.brainTick
local drawTick = S.drawTick
local lobbyTick = S.lobbyTick
local autosaveTick = S.autosaveTick
local loadConfig = S.loadConfig
local startAutosave = S.startAutosave
local buildUI = S.buildUI
local releaseMover = S.releaseMover
local setMovementState = S.setMovementState
local heavyDebugThrottled = S.heavyDebugThrottled

print(string.format("DUNGEON AUTOFARM %s  |  build %s  |  %d hazards known by name", SCRIPT_VERSION, SCRIPT_BUILD_DATE, (function() local n = 0 for _ in pairs(S.TIMING) do n = n + 1 end return n end)()))

loadConfig()
startAutosave()
buildUI()
readerStart()
setMovementState("ready")

RT.mainConnection = RunService.Heartbeat:Connect(function(delta)
    if RT.destroyed then return end
    RT.frameDelta = delta or (1 / 60)
    local t0 = os.clock()
    local now = t0
    local ok, err = pcall(function()
        readerTick(now)
        lobbyTick(now)
        autosaveTick(now)
        if RT.farmEnabled then
            brainTick(now)
        else
            local c = LocalPlayer.Character
            releaseMover(c and c:FindFirstChildOfClass("Humanoid"), c and c:FindFirstChild("HumanoidRootPart"))
            setMovementState("off")
        end
        drawTick(now)
    end)
    if not ok then heavyDebugThrottled("main_err", 1, "Main", tostring(err)) end
    RT.tickMs = (RT.tickMs or 0) * 0.9 + (os.clock() - t0) * 1000 * 0.1
end)
end
    end)()
    module(S)
end
